{
  "profile_id": "custom-lite",
  "description": "Custom Lite（custom_private 模式）的成本围栏：低价自动定制测试只在此围栏内生产。这里写死的是硬约束；逐项豁免是商务决定，不走工厂流程。",
  "applies_to_commercial_modes": ["custom_private"],
  "constraints": {
    "question_count": { "min": 12, "max": 16 },
    "result_count": { "min": 6, "max": 8 },
    "layout": {
      "value": "preset_mobile_v1",
      "description": "使用预设移动端布局（现有皮肤 skin.js/skin.css 结构），不做独立的交互设计或动效定制。"
    },
    "visual": {
      "mode": "preset",
      "independent_ai_illustration": false,
      "preset_visual_families": [
        "literary-ink（文学皮肤风：单面立绘位 + 纯文字结果卡）",
        "vase-flat（陶绘平涂刻线风：单面卡，沿用五色族语法，不做双面卡）",
        "cute-flat（猫咪/迪士尼系平涂可爱风）"
      ],
      "description": "从预设视觉族中选一种套用；默认不生成全套独立 AI 插画，结果卡用预设族的符号化美术兜底。"
    },
    "interaction": {
      "independent_design": false,
      "description": "答题流程、翻卡、分享图等交互全部沿用预设布局，不改 app.js。"
    },
    "domain": {
      "value": "shared",
      "custom_domain": false,
      "description": "挂在现有站点共享域名下（/t/<product_id>），不提供自定义域名。"
    },
    "commercial_hosting": {
      "value": false,
      "description": "不附带商业托管权：客户不得将测试用于自己的对外售卖/收费场景；需要则升级 hosted_creator 并另立约定。"
    },
    "backend": {
      "value": "shared_server",
      "description": "复用现有 server（兑换码/评分/绑定全套现成能力），不提供独立 license server、独立数据库或 admin 权限。"
    }
  },
  "inclusions": [
    "完整题库（12–16 题 × 3 选项，含权重与归一化）",
    "6–8 个原创结果原型 + 结果文案",
    "预设视觉族套用 + 兑换码门 + 分享图（预设布局）",
    "标准上线验证 + 一定数量的兑换码（按订单铸发）"
  ],
  "exclusions": [
    "全套独立 AI 插画（每结果定制立绘/双面卡）",
    "独立交互设计、独立动效、独立视觉系统文档",
    "自定义域名、独立部署、独立 license server / 数据库 / admin 权限",
    "商业托管权、分账、创作者后台",
    "题目内容之后的持续内容运营（迭代按新订单计）"
  ],
  "escalation_path": "客户需求超出围栏时，升级到 hosted_creator（托管合作）或按 internal 全流水线报价；不做『围栏内砍价』。"
}

