  const norm = (c) => String(c || "").toUpperCase().replace(/[\s-]+/g, "");
  const path = String(url).split("?")[0];
  if (path === "/api/redeem") {
    if (norm(body.code) !== norm(CODE)) return json(404, { ok: false, error: "invalid_code" });
    if (!activated) {
      activated = true;
      return json(200, { ok: true, secret: SECRET, firstUse: true, product_id: "weather-station", product_name: "情绪气象台：你的内心天气观测报告" });
    }
    if (body.secret === SECRET) return json(200, { ok: true, secret: SECRET, firstUse: false, product_id: "weather-station", product_name: "情绪气象台：你的内心天气观测报告" });
