/* --------------------------------------------------------- 流程 ---- */
await check("boot renders the weather-station skin, not the default gate", () => {
  assert(appEl.querySelector(".wx-title"), "weather-station gate title missing");
  assert(appEl.querySelector(".wx-gate-form"), "gate form missing");
  assert(!appEl.querySelector(".gate-hero"), "default gate template leaked into skin flow");
  assert(bodyEl.attributes["data-skin"] === "weather-station", "body data-skin not set");
  assert(globalThis.document.title === "情绪气象台：你的内心天气观测报告", `skin title wrong: ${globalThis.document.title}`);
  return "entrance";
});

await check("a valid code unlocks the cover with the 7-weather cast row", async () => {
  const input = appEl.querySelector("#wx-gate-code");
  const submit = appEl.querySelector("#wx-gate-submit");
  input.value = CODE.toLowerCase();
  submit.click();
  await sleep(120);
  assert(appEl.querySelector(".wx-cover"), "cover missing after redeem");
  assert(appEl.querySelector(".wx-cover .wx-title").textContent.includes("哪种天气"), "cover title wrong");
  assert(appEl.querySelectorAll(".wx-cast-dot").length === 7, "cast row must show 7 weathers");
  assert(appEl.querySelector("#wx-start"), "start button missing");
  const stored = JSON.parse(globalThis.localStorage.getItem("mythic.license.v1") || "null");
  assert(stored && stored.secret === SECRET, "license not persisted");
  return "cover";
});

await check("starting shows question 1 of 14 with three options and a progress bar", async () => {
  appEl.querySelector("#wx-start").click();
  await sleep(80);
  assert(appEl.querySelector(".wx-q-count").textContent.includes("第 1 次记录"), `expected Q1, got ${appEl.querySelector(".wx-q-count")?.textContent}`);
  assert(appEl.querySelectorAll(".wx-option").length === 3, "three options expected");
  assert(appEl.querySelector(".wx-progress i"), "progress bar missing");
  return "Q1";
});

await check("picking an option colors it and advances", async () => {
  appEl.querySelectorAll(".wx-option")[1].click();
  await sleep(60);
  assert(appEl.querySelectorAll(".wx-option")[1].classList.contains("picked"), "option must be picked before advancing");
  await sleep(340);
  assert(appEl.querySelector(".wx-q-count").textContent.includes("第 2 次记录"), "did not advance to Q2");
  appEl.querySelector("#wx-prev").click();
  await sleep(50);
  assert(appEl.querySelector(".wx-q-count").textContent.includes("第 1 次记录"), "上一条 failed");
  assert(appEl.querySelectorAll(".wx-option")[1].classList.contains("picked"), "returning must show the recorded pick");
  return "pick + back";
});

await check("a full 14-question run lands on a named result page", async () => {
  for (let i = 0; i < 14; i += 1) {
    const count = appEl.querySelector(".wx-q-count");
    assert(count, `question ${i + 1} missing`);
    appEl.querySelectorAll(".wx-option")[0].click();
    await sleep(340);
  }
  const name = appEl.querySelector(".wx-name");
  assert(name, "result name missing");
  const quote = appEl.querySelector(".wx-quote");
  assert(quote && quote.textContent.trim().length > 4, "share_line missing");
  const reading = appEl.querySelector(".wx-reading");
  assert(reading && reading.textContent.trim().length > 40, "reading portrait missing");
  assert(appEl.querySelector("#wx-share"), "save button missing");
  for (const id of ["#wx-copy", "#wx-again", "#wx-home"]) {
    assert(appEl.querySelector(id), `action ${id} missing`);
  }
  return `天气：${name.textContent}`;
});

await check("result page carries the persona accent, SVG art slot and observation stamp", () => {
  const section = appEl.querySelector(".wx-result");
  assert(section.attributes.style && section.attributes.style.includes("--wx-accent"), "accent color not set on result");
  const img = appEl.querySelector(".wx-portrait img");
  assert(img, "portrait slot missing");
  assert(String(img.attributes.src).startsWith("/assets/weather-station/"), `art path wrong: ${img.attributes.src}`);
  assert(String(img.attributes.src).endsWith(".svg"), "station-card family ships SVG observation cards");
  const stamp = appEl.querySelector(".wx-top-right");
  assert(stamp && /OBS\.\d{2}/.test(stamp.textContent), "observation stamp missing");
  return "accent + svg art + stamp";
});

await check("share and copy actions work inside the skin", async () => {
  canvasCreated = 0;
  appEl.querySelector("#wx-share").click();
  appEl.querySelector("#wx-copy").click();
  await sleep(60);
  const copy = appEl.querySelector("#wx-copy");
  assert(copy.textContent.includes("已复制"), `copy feedback wrong: ${copy.textContent}`);
  assert(canvasCreated >= 1, "share must build a canvas image");
  return "share + copy";
});

await check("again restarts at Q1, exit returns to the cover", async () => {
  appEl.querySelector("#wx-again").click();
  await sleep(60);
  assert(appEl.querySelector(".wx-q-count").textContent.includes("第 1 次记录"), "再测一次 failed");
  appEl.querySelector("#wx-exit").click();
  await sleep(60);
  assert(appEl.querySelector(".wx-cover"), "回封面 failed");
  return "again + exit";
});

await check("scoring actually went through the server-side declared model", () => {
  assert(lastScoreTheme === "weather-station", "score API was not called with the weather-station theme");
  const theme = WX_THEMES[0];
  assert(theme.scoring && theme.scoring.normalization_bounds, "theme must declare the normalized scoring model");
  return `theme ${lastScoreTheme} scored server-side`;
});

/* ------------------------------------------------------- 可达性 ---- */
check("all 7 weathers are reachable under the real scoring algorithm", () => {
  const theme = WX_THEMES[0];
  const ids = theme.results.map((r) => r.id);
  assert(ids.length === 7, `expected 7 results, got ${ids.length}`);
  const runs = 200;
  let seed = 84848;
  const rand = () => {
    seed = (seed * 1103515245 + 12345) & 0x7fffffff;
    return seed / 0x7fffffff;
  };
  for (const id of ids) {
    let wins = 0;
    for (let run = 0; run < runs; run += 1) {
      const answers = theme.questions.map((question) => {
        const best = question.options
          .map((o, i) => ({ i, s: o.scores[id] || 0 }))
          .sort((a, b) => b.s - a.s);
        const topScore = best[0].s;
        const topOptions = best.filter((b) => b.s === topScore).map((b) => b.i);
        if (rand() < 0.8) return topOptions[Math.floor(rand() * topOptions.length)];
        return Math.floor(rand() * question.options.length);
      });
      const { winnerId } = selectWinner(theme, answers);
      if (winnerId === id) wins += 1;
      if (run === 0) {
        const full = theme.questions.map((question) =>
          question.options
            .map((o, i) => ({ i, s: o.scores[id] || 0 }))
            .sort((a, b) => b.s - a.s)[0].i);
        const verdict = selectWinner(theme, full);
        assert(verdict.winnerId === id, `full-leaning run elects ${verdict.winnerId} for ${id}`);
      }
    }
    const rate = wins / runs;
    assert(rate >= 0.8, `${id} leaning win-rate ${(rate * 100).toFixed(1)}% < 80%`);
  }
  return "7/7 reachable";
});

/* ------------------------------------------------------- 隔离检查 ---- */
check("skin.css is fully scoped and does not touch other products", () => {
  const stripped = skinCss.replace(/\/\*[\s\S]*?\*\//g, "");
  let depth = 0;
  for (const line of stripped.split("\n")) {
    const trimmed = line.trim();
    if (!trimmed) continue;
    const opens = (trimmed.match(/{/g) || []).length;
    const closes = (trimmed.match(/}/g) || []).length;
    if (trimmed.endsWith("{") && opens === 1) {
      if (!/^(body\[data-skin|@media|@keyframes|from|to|\d+%)/.test(trimmed)) {
        throw new Error(`unscoped selector: ${trimmed}`);
      }
    }
    depth += opens - closes;
  }
  assert(depth === 0, "unbalanced braces in skin.css");
  for (const foreign of ["lw-", "pp-", "ggw-", "dp-", "cat-", "dpp-"]) {
    assert(!skinCss.includes(foreign), `skin.css must not reference ${foreign} (cross-product leak)`);
  }
  return "scoped, no cross-product selectors";
});

check("skin classes used by skin.js all exist in skin.css", () => {
  const js = readFileSync(join(ROOT, "deploy-ready", "themes", "weather-station", "skin.js"), "utf8");
  const used = new Set(
    [...js.matchAll(/class="([^"]*)"/g)].flatMap((m) => m[1].split(/\s+/))
      .flatMap((c) => c.match(/wx-[a-z0-9-]+/g) || [])
  );
  const hooks = new Set(["wx-top-right", "wx-option-text", "wx-q"]);
  const defined = new Set([...skinCss.matchAll(/\.(wx-[a-z0-9-]+)/g)].map((m) => m[1]));
  const missing = [...used].filter((c) => !defined.has(c) && !hooks.has(c));
  assert(missing.length === 0, `classes without CSS: ${missing.join(", ")}`);
  return `${used.size} classes covered`;
});

check("the skin carries no scoring, network or content-file logic", () => {
  const js = readFileSync(join(ROOT, "deploy-ready", "themes", "weather-station", "skin.js"), "utf8");
  for (const banned of ["normalization_bounds", "selectWinner", "quiz_content_upgrade", "weather_station.json", "fetch("]) {
    assert(!js.includes(banned), `skin must not contain ${banned}`);
  }
  return "expression only";
});

check("the content file is this product's own private matrix", () => {
  const manifest = JSON.parse(readFileSync(join(ROOT, "server", "content", "products", "weather-station", "product.json"), "utf8"));
  assert(manifest.name === "情绪气象台：你的内心天气观测报告", "product name must be weather-station");
  assert(manifest.content_file === "../../weather_station.json", "must own its private content file");
  const raw = JSON.parse(readFileSync(join(ROOT, "server", "content", "weather_station.json"), "utf8"));
  assert(raw.themes.length === 1 && raw.themes[0].id === "weather-station", "private file must hold only this theme");
  assert(raw.themes[0].questions.length === 14, "14 questions");
  assert(raw.themes[0].results.length === 7, "7 results");
  assert(!appSource.includes("wx-"), "default templates must not reference wx- classes");
  return "own matrix, own file";
});

delete globalThis.__MYTHIC_SKINS__;

/* --------------------------------------------------------- 汇总 ---- */
const failures = results.filter((r) => !r.ok);
console.log("\n情绪气象台皮肤 · 流程测试\n");
for (const r of results) console.log(`  ${r.ok ? "PASS" : "FAIL"}  ${r.name}${r.d ? " — " + r.d : ""}`);
console.log(`\n${results.length - failures.length}/${results.length} passed`);
process.exit(failures.length ? 1 : 0);

