348:.flip-card .back h2 { color: #c98b72; }
350:.flip-card .reading { margin: 0; color: #514940; font-size: 14px; line-height: 1.7; -webkit-line-clamp: none; display: block; overflow: visible; }
351:.flip-card .back .reading { color: #e0d5c6; }
354:.flip-card .face.art-missing .art { background: linear-gradient(135deg, color-mix(in srgb, var(--accent) 22%, var(--surface)), var(--surface)); }
361:  .flip-card .face {
364:  .flip-card .front { opacity: 1; }
365:  .flip-card.is-back .front { opacity: 0; }
366:  .flip-card .back { opacity: 0; }
367:  .flip-card.is-back .back { opacity: 1; }
392:  .flip-card { min-height: 660px; }
393:  .flip-card .body { padding: 16px; }
394:  .flip-card .eyebrow { font-size: 22px; }
395:  .result-card { padding: 16px; }
396:  .result-card .visual-art { margin: -16px -16px 20px; height: 164px; }

465:.result-hera.card-peek-1 { animation-name: card-gaze; animation-duration: 1.7s; }
466:.result-hera.card-peek-2 { animation-name: card-gaze; animation-duration: 2s; }
473:.result-aphrodite.card-peek-1 { animation-duration: 1.4s; }
474:.result-aphrodite.card-peek-2 { animation-duration: 1.55s; }
477:.result-artemis.card-peek-1 { animation-duration: 1.05s; }
478:.result-artemis.card-peek-2 { animation-duration: 1.15s; }
481:.result-hecate.card-peek-1 { animation-duration: 1.5s; }
482:.result-hecate.card-peek-2 { animation-duration: 1.65s; }
487:.result-demeter.card-peek-1 { animation-duration: 1.4s; }
488:.result-demeter.card-peek-2 { animation-duration: 1.5s; }
491:.result-medea.card-peek-1 { animation-duration: .9s; }
492:.result-medea.card-peek-2 { animation-duration: 1s; }
495:.result-atalanta.card-peek-1 { animation-duration: .85s; }
496:.result-atalanta.card-peek-2 { animation-duration: .95s; }
499:.result-circe.card-peek-1 { animation-duration: 1.5s; }
500:.result-circe.card-peek-2 { animation-duration: 1.65s; }
505:  .flip-card.card-arrive,
506:  .flip-card.card-peek-1,
507:  .flip-card.card-peek-2,
508:  .flip-card.is-flipping { animation: none; }
---

/* ============================================================ 卡片微交互（V2 CARD_MOTION）====
   卡是物理收藏品，不是 UI 面板：落卡（入场）、倾角（悬停）、探视（邀请翻面）、
   升力（翻面）、按压（active）。邀请最多两次，之后永远安静 —— 动效只负责
   教会「翻面」这一件事。所有动作只用 transform / opacity / box-shadow，
   不触发 layout；flavor 挂在既有的 result-<id> 类上。                          */

/* 落卡：结果渲染时，卡片像被放到桌面上 */
@keyframes card-arrive {
  0% { transform: translateY(16px) rotateX(6deg); opacity: 0; }
  100% { transform: translateY(0) rotateX(0); opacity: 1; }
}
.flip-card.card-arrive { animation: card-arrive .52s cubic-bezier(.2,.7,.2,1) both; will-change: transform; }

/* 探视一（3 秒无触碰）：向左轻侧 8°，像有人掀卡角示意还有另一面 */
@keyframes card-peek-1 {
  0% { transform: rotateY(0) rotateZ(0); }
  38% { transform: rotateY(-8deg) rotateZ(.35deg); }
  58% { transform: rotateY(-6deg) rotateZ(-.2deg); }
  100% { transform: rotateY(0) rotateZ(0); }
}
.flip-card.card-peek-1 { animation: card-peek-1 1.15s cubic-bezier(.2,.7,.2,1) 1; will-change: transform; }

/* 探视二（7.5 秒仍无触碰）：幅度更大并轻微离桌，然后就此打住 */
@keyframes card-peek-2 {
  0% { transform: rotateY(0) rotateZ(0) translateY(0); }
  40% { transform: rotateY(-12deg) rotateZ(-.5deg) translateY(-5px); }
  62% { transform: rotateY(-9.5deg) rotateZ(.3deg) translateY(-4px); }
  100% { transform: rotateY(0) rotateZ(0) translateY(0); }
}
.flip-card.card-peek-2 { animation: card-peek-2 1.3s cubic-bezier(.2,.7,.2,1) 1; will-change: transform; }

/* 升力：翻面瞬间卡片离桌一点再落回，与 0.7s 面旋转同步 */
@keyframes card-flip-lift {
  0% { transform: translateY(0) scale(1); }
  50% { transform: translateY(-10px) scale(1.012); }
  100% { transform: translateY(0) scale(1); }
}
.flip-card.is-flipping { animation: card-flip-lift .7s cubic-bezier(.2,.7,.2,1) 1; will-change: transform; }

/* 悬停倾角与按压：物体被手触碰时的物理反馈 */
.flip-card { transition: transform .18s ease; }
@media (hover:hover) and (pointer:fine) {
  .flip-card:not(.is-back):hover { transform: rotateX(1deg) rotateY(-2deg); }
  .flip-card.is-back:hover { transform: rotateX(1deg) rotateY(2deg); }
}
.flip-card:active { transform: scale(.985); }

/* ---- 每位一缕风（flavor）----
   Hestia 火光：影染炭橙，探视放慢，像炉火的节拍；       */
.result-hestia.flip-card .front { box-shadow: 0 18px 36px rgba(150,74,20,.24); }
.result-hestia.flip-card .back { box-shadow: 0 22px 30px rgba(66,30,8,.5); }
.result-hestia.card-peek-1 { animation-duration: 1.45s; }
.result-hestia.card-peek-2 { animation-duration: 1.6s; }
/* Nike 风息：悬停倾角更大、探视更轻快，像翼下有风； */
@media (hover:hover) and (pointer:fine) {
  .result-nike.flip-card:not(.is-back):hover { transform: rotateX(1.2deg) rotateY(-3.2deg); }
}
.result-nike.card-peek-1 { animation-duration: .95s; }
.result-nike.card-peek-2 { animation-duration: 1.05s; }
/* Hera 凝视：不旋转，缓缓向你压近一寸，影染钴青。 */
@keyframes card-gaze {
  0% { transform: scale(1); }
  45% { transform: scale(1.02); }
  100% { transform: scale(1); }
}
.result-hera.card-peek-1 { animation-name: card-gaze; animation-duration: 1.7s; }
.result-hera.card-peek-2 { animation-name: card-gaze; animation-duration: 2s; }
.result-hera.flip-card .front { box-shadow: 0 18px 36px rgba(34,48,74,.26); }
.result-hera.flip-card .back { box-shadow: 0 22px 30px rgba(10,16,32,.55); }
/* Athena 冷静：影偏冷灰，标准节拍 */
.result-athena.flip-card .front { box-shadow: 0 18px 36px rgba(52,62,80,.22); }
/* Aphrodite 温柔：影染玫瑰，探视放缓 */
.result-aphrodite.flip-card .front { box-shadow: 0 18px 36px rgba(148,74,96,.22); }
.result-aphrodite.card-peek-1 { animation-duration: 1.4s; }
.result-aphrodite.card-peek-2 { animation-duration: 1.55s; }
/* Artemis 警觉：影染橄榄，探视轻快 */
.result-artemis.flip-card .front { box-shadow: 0 18px 36px rgba(74,90,58,.22); }
.result-artemis.card-peek-1 { animation-duration: 1.05s; }
.result-artemis.card-peek-2 { animation-duration: 1.15s; }
/* Hecate 夜行：影最深，探视最慢（夜的节拍） */
.result-hecate.flip-card .front { box-shadow: 0 18px 36px rgba(16,22,40,.34); }
.result-hecate.card-peek-1 { animation-duration: 1.5s; }
.result-hecate.card-peek-2 { animation-duration: 1.65s; }
/* Persephone 两界：影染酒色，中速 */
.result-persephone.flip-card .front { box-shadow: 0 18px 36px rgba(90,42,66,.24); }
/* Demeter 沉稳：影染赭金，慢而稳 */
.result-demeter.flip-card .front { box-shadow: 0 18px 36px rgba(140,96,36,.24); }
.result-demeter.card-peek-1 { animation-duration: 1.4s; }
.result-demeter.card-peek-2 { animation-duration: 1.5s; }
/* Medea 决断：影染深酒，探视利落 */
.result-medea.flip-card .front { box-shadow: 0 18px 36px rgba(64,24,38,.28); }
.result-medea.card-peek-1 { animation-duration: .9s; }
.result-medea.card-peek-2 { animation-duration: 1s; }
/* Atalanta 冲刺：全套最快 */
.result-atalanta.flip-card .front { box-shadow: 0 18px 36px rgba(96,104,50,.2); }
.result-atalanta.card-peek-1 { animation-duration: .85s; }
.result-atalanta.card-peek-2 { animation-duration: .95s; }
/* Circe 岛时：影染螺紫，慢 */
.result-circe.flip-card .front { box-shadow: 0 18px 36px rgba(78,48,92,.26); }
.result-circe.card-peek-1 { animation-duration: 1.5s; }
.result-circe.card-peek-2 { animation-duration: 1.65s; }

/* 减少运动：一切位移归零；翻面沿用上面的透明度交叉淡入，提示文案静态出现 */
@media (prefers-reduced-motion: reduce) {
  .flip-card { transition: none; }
  .flip-card.card-arrive,
  .flip-card.card-peek-1,
  .flip-card.card-peek-2,
  .flip-card.is-flipping { animation: none; }
}

input.content:
/* 希腊女神测试 —— 产品视觉层样式（陶绘 vase 语言）
 *
 * 作用域：全部规则挂在 body[data-skin="greek_goddess"] 下，与默认模板和
 * 其他产品皮肤完全隔离。
 *
 * 世界观：陶绘（红绘/黑绘）。陶纸底带拉坯细纹、夜蓝图底、陶土点缀、刻线双框；
 * 结果卡正面 = 红绘（浅底 + 陶土人物），背面 = 黑绘（夜蓝底 + 米金文字），
 * 与 V2 视觉系统的正/背图底反转同构。卡片内部复用默认模板的
 * .flip-card/.face/.art 结构，落卡/探视/升力动效类（card-arrive 等）
 * 来自全局 styles.css，本文件只重塑颜色、字体与边框，不与之对抗。
 */

body[data-skin="greek_goddess"] {
  --gg-ink: #232E3A;          /* 夜蓝：图底与文字 */
  --gg-clay: #A6472F;         /* 陶土：红绘点缀 */
  --gg-gold: #B98A44;         /* 金赭：背面文字 */
  --gg-olive: #6B6B45;
  --gg-violet: #6E4A6B;
  --gg-paper: #F3EEE2;        /* 陶纸 */
  --gg-card: #F8F3E8;
  --gg-soft: #6E6A5E;
  --gg-hairline: rgba(35, 46, 58, 0.4);
  --gg-serif: "Songti SC", "STSong", "Noto Serif SC", "SimSun", Georgia, serif;

  margin: 0;
  color: var(--gg-ink);
  font-family: var(--gg-serif);
  background-color: var(--gg-paper);
  background-image: repeating-linear-gradient(
    0deg, transparent 0 15px, rgba(35, 46, 58, 0.028) 15px 16px);
}

body[data-skin="greek_goddess"] .gg {
  max-width: 640px;
  min-height: 100vh;
  min-height: 100dvh;
  margin: 0 auto;
  padding: 14px 16px calc(28px + env(safe-area-inset-bottom, 0px));
}

/* ---------------------------------------------------------------- 骨架 ---- */
body[data-skin="greek_goddess"] .gg-top {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 14px;
  color: var(--gg-soft);
  font-size: 12px;
  letter-spacing: .12em;
}

body[data-skin="greek_goddess"] .gg-brand {
  color: var(--gg-ink);
  font-weight: 700;
  letter-spacing: .1em;
}

body[data-skin="greek_goddess"] .gg-eyebrow {
  margin: 0 0 10px;
  color: var(--gg-clay);
  font: 600 11px/1 Georgia, serif;
  letter-spacing: .32em;
  text-transform: uppercase;
}

body[data-skin="greek_goddess"] .gg-title {
  margin: 6px 0 12px;
  font-size: clamp(27px, 7.4vw, 41px);
  font-weight: 700;
  line-height: 1.52;
  letter-spacing: .02em;
}

body[data-skin="greek_goddess"] .gg-lead {
  margin: 0 auto;
  max-width: 26em;
  color: var(--gg-soft);
  font-size: 14.5px;
  line-height: 1.95;
}

body[data-skin="greek_goddess"] .gg-foot {
  margin: 24px 0 0;
  color: #8D8672;
  font-size: 11.5px;
  line-height: 1.8;
}

/* ---------------------------------------------------------------- 卡片 ----
   刻线双框：1.5px 实线 + 3px 纸底间隔 + 1px 发丝线 */
body[data-skin="greek_goddess"] .gg-card {
  max-width: 460px;
  margin: 0 auto;
  padding: 30px 26px;
  border: 1.5px solid var(--gg-ink);
  border-radius: 2px;
  background: var(--gg-card);
  box-shadow:
    0 0 0 3px var(--gg-paper),
    0 0 0 4px var(--gg-hairline);
}

/* ---------------------------------------------------------------- 按钮 ---- */
body[data-skin="greek_goddess"] .gg-btn {
  padding: 13px 44px;
  border: 1.5px solid var(--gg-ink);
  border-radius: 2px;
  background: var(--gg-ink);
  color: #F3EEE2;
  font: 700 15.5px/1 var(--gg-serif);
  letter-spacing: .22em;
  text-indent: .22em;
  cursor: pointer;
  transition: background-color .18s ease, border-color .18s ease;
}

body[data-skin="greek_goddess"] .gg-btn:hover { background: #17202A; border-color: #17202A; }
body[data-skin="greek_goddess"] .gg-btn-big { padding: 14px 50px; font-size: 16px; }

body[data-skin="greek_goddess"] .gg-link {
  padding: 2px 0;
  border: 0;
  border-bottom: 1.5px solid rgba(35, 46, 58, .3);
  background: transparent;
  color: var(--gg-soft);
  font: 500 13px/1.5 var(--gg-serif);
  letter-spacing: .1em;
  cursor: pointer;
}

body[data-skin="greek_goddess"] .gg-link:hover { color: var(--gg-clay); border-color: var(--gg-clay); }
body[data-skin="greek_goddess"] .gg-link:disabled { opacity: .35; cursor: not-allowed; }

/* ---------------------------------------------------------------- 入场 ---- */
body[data-skin="greek_goddess"] .gg-gate { margin-top: 7vh; text-align: center; }

body[data-skin="greek_goddess"] .gg-gate-lead { margin: 0 0 22px; }

body[data-skin="greek_goddess"] .gg-gate-form { display: flex; gap: 10px; }

body[data-skin="greek_goddess"] .gg-gate-input {
  flex: 1;
  min-width: 0;
  padding: 12px 14px;
  border: 1.5px solid var(--gg-hairline);
  border-radius: 2px;
  background: #FFFDF6;
  color: var(--gg-ink);
  font: 600 14px/1.4 ui-monospace, "SF Mono", Consolas, monospace;
  letter-spacing: .06em;
}

body[data-skin="greek_goddess"] .gg-gate-input:focus-visible {
  outline: 0;
  border: 2px solid var(--gg-clay);
}

body[data-skin="greek_goddess"] .gg-gate .gg-btn { padding: 13px 30px; }

body[data-skin="greek_goddess"] .gg-gate-error {
  min-height: 20px;
  margin: 12px 0 0;
  color: var(--gg-clay);
  font-size: 13px;
}

/* ---------------------------------------------------------------- 封面 ---- */
body[data-skin="greek_goddess"] .gg-cover { margin-top: 4vh; text-align: center; }

body[data-skin="greek_goddess"] .gg-cast {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px;
  margin: 16px 0 4px;
}

body[data-skin="greek_goddess"] .gg-cast-dot {
  width: 18px;
  height: 18px;
  border-radius: 50%;
  border: 1.5px solid rgba(35, 46, 58, .35);
  transition: transform .16s ease;
}

body[data-skin="greek_goddess"] .gg-cast-dot:hover { transform: scale(1.22); border-color: var(--gg-ink); }
body[data-skin="greek_goddess"] .gg-cover-actions { margin: 22px 0 0; }

/* ---------------------------------------------------------------- 答题 ---- */
body[data-skin="greek_goddess"] .gg-progress {
  height: 6px;
  margin: 2px 2px 14px;
  border: 1px solid var(--gg-hairline);
  background:
    repeating-linear-gradient(90deg, transparent 0 13px, rgba(35, 46, 58, 0.16) 13px 14px);
  overflow: hidden;
}

body[data-skin="greek_goddess"] .gg-progress i {
  display: block;
  height: 100%;
  background: var(--gg-clay);
  transition: width .3s ease;
}

body[data-skin="greek_goddess"] .gg-q-count {
  margin: 0 0 6px;
  color: var(--gg-soft);
  font: 700 12px/1 Georgia, serif;
  letter-spacing: .24em;
}

body[data-skin="greek_goddess"] .gg-q-text {
  margin: 0 0 12px;
  padding: 16px 18px;
  border: 1.5px solid var(--gg-ink);
  border-radius: 2px;
  background: var(--gg-card);
  box-shadow: 0 0 0 3px var(--gg-paper), 0 0 0 4px var(--gg-hairline);
  font-size: clamp(20px, 5.4vw, 26px);
  font-weight: 700;
  line-height: 1.62;
}

body[data-skin="greek_goddess"] .gg-options { display: grid; gap: 10px; }

body[data-skin="greek_goddess"] .gg-option {
  display: flex;
  gap: 12px;
  align-items: center;
  padding: 12px 15px;
  border: 1.5px solid var(--gg-hairline);
  border-radius: 2px;
  background: var(--gg-card);
  color: var(--gg-ink);
  font: 400 15px/1.68 var(--gg-serif);
  text-align: left;
  cursor: pointer;
  transition: border-color .16s ease, background-color .16s ease;
  animation: gg-rise .4s cubic-bezier(.2, .7, .2, 1) both;
}

body[data-skin="greek_goddess"] .gg-option:nth-child(2) { animation-delay: .06s; }
body[data-skin="greek_goddess"] .gg-option:nth-child(3) { animation-delay: .12s; }

body[data-skin="greek_goddess"] .gg-option:hover { border-color: var(--gg-clay); }

body[data-skin="greek_goddess"] .gg-option-key {
  display: grid;
  flex: 0 0 28px;
  width: 28px;
  height: 28px;
  place-items: center;
  border: 1.5px solid var(--gg-hairline);
  border-radius: 2px;
  color: var(--gg-soft);
  font: 700 12.5px/1 Georgia, serif;
}

body[data-skin="greek_goddess"] .gg-option.picked {
  border-color: var(--gg-clay);
  background: color-mix(in srgb, var(--gg-clay) 8%, var(--gg-card));
}

body[data-skin="greek_goddess"] .gg-option.picked .gg-option-key {
  border-color: var(--gg-clay);
  background: var(--gg-clay);
  color: #F3EEE2;
}

@keyframes gg-rise {
  0% { opacity: 0; transform: translateY(8px); }
  100% { opacity: 1; transform: translateY(0); }
}

body[data-skin="greek_goddess"] .gg-q-nav {
  display: flex;
  justify-content: space-between;
  margin-top: 12px;
}

/* ---------------------------------------------------------------- 等待 ---- */
body[data-skin="greek_goddess"] .gg-loading { margin-top: 10vh; text-align: center; }

body[data-skin="greek_goddess"] .gg-loading-text {
  margin: 8px 0 4px;
  font-weight: 700;
  font-size: 16px;
  letter-spacing: .16em;
}

/* ---------------------------------------------------------------- 结果 ----
   卡片内部复用默认模板结构（.flip-card/.face/.art/.body）以继承翻面与
   CARD_MOTION 动效；此处只做陶绘重塑。 */

body[data-skin="greek_goddess"] .gg-result { margin-top: 1vh; }

body[data-skin="greek_goddess"] .gg-result .scene { margin: 0 0 4px; }

body[data-skin="greek_goddess"] .gg-result .flip-card {
  border: 1.5px solid var(--gg-ink);
  border-radius: 2px;
  background: var(--gg-card);
  box-shadow: 0 0 0 3px var(--gg-paper), 0 0 0 4px var(--gg-hairline);
}

body[data-skin="greek_goddess"] .gg-result .flip-card .art {
  border: 0;
  border-bottom: 1.5px solid var(--gg-hairline);
  border-radius: 0;
  background: #EFE7D6;
}

body[data-skin="greek_goddess"] .gg-result .flip-card .body { padding: 18px 22px 16px; }

/* 正面 = 红绘：浅底、陶土点缀 */
body[data-skin="greek_goddess"] .gg-result .face.front .body { background: transparent; }
body[data-skin="greek_goddess"] .gg-result .face.front .eyebrow {
  color: var(--gg-ink);
  font: 700 26px/1.15 var(--gg-serif);
}
body[data-skin="greek_goddess"] .gg-result .face.front .eyebrow small {
  color: var(--gg-soft);
  font: 400 14px/1 Georgia, serif;
  letter-spacing: .05em;
}
body[data-skin="greek_goddess"] .gg-result .face.front h2 { color: var(--gg-clay); }
body[data-skin="greek_goddess"] .gg-result .face.front .reading { color: #514A3E; }

/* 背面 = 黑绘：夜蓝底、米金文字 */
body[data-skin="greek_goddess"] .gg-result .face.back .body { background: var(--gg-ink); }
body[data-skin="greek_goddess"] .gg-result .face.back .eyebrow { color: #E8DCC8; font: 700 26px/1.15 var(--gg-serif); }
body[data-skin="greek_goddess"] .gg-result .face.back .eyebrow small { color: var(--gg-gold); font: 400 14px/1 Georgia, serif; }
body[data-skin="greek_goddess"] .gg-result .face.back h2 { color: #C98B72; }
body[data-skin="greek_goddess"] .gg-result .face.back .reading { color: #D8CCB8; }
