/* --------------------------------------------- 挂载真实皮肤并启动 ---- */
const skinModule = await import(pathToFileURL(join(ROOT, "deploy-ready", "themes", "greek_goddess", "skin.js")).href);
globalThis.__MYTHIC_SKINS__ = { "greek_goddess": skinModule.default };

const appSource = readFileSync(join(ROOT, "deploy-ready", "app.js"), "utf8");
new Function("module", "exports", appSource)({ exports: {} }, {});
await sleep(80);

const skinCss = readFileSync(join(ROOT, "deploy-ready", "themes", "greek_goddess", "skin.css"), "utf8");

/* --------------------------------------------------------- 流程 ---- */
await check("boot renders the greek_goddess skin, not the default gate", () => {
  assert(appEl.querySelector(".gg-title"), "greek gate title missing");
  assert(appEl.querySelector(".gg-gate-form"), "gate form missing");
  assert(!appEl.querySelector(".gate-hero"), "default gate template leaked into skin flow");
