  return `theme ${lastScoreTheme} scored server-side`;
});

/* ------------------------------------------------------- 可达性 ---- */
check("all 12 goddesses are reachable under the real scoring algorithm", () => {
  const theme = GG_THEMES[0];
  const ids = theme.results.map((r) => r.id);
  assert(ids.length === 12, `expected 12 results, got ${ids.length}`);
  const runs = 200;
  let seed = 84848;
  const rand = () => {
    seed = (seed * 1103515245 + 12345) & 0x7fffffff;
    return seed / 0x7fffffff;
  };
  for (const id of ids) {
    let wins = 0;
    for (let run = 0; run < runs; run += 1) {
      const answers = theme.questions.map((question) => {
        const best = question.options
          .map((o, i) => ({ i, s: o.scores[id] || 0 }))
          .sort((a, b) => b.s - a.s);
        const topScore = best[0].s;
        const topOptions = best.filter((b) => b.s === topScore).map((b) => b.i);
        if (rand() < 0.8) return topOptions[Math.floor(rand() * topOptions.length)];
        return Math.floor(rand() * question.options.length);
      });
      const { winnerId } = selectWinner(theme, answers);
      if (winnerId === id) wins += 1;
      if (run === 0) {
        const full = theme.questions.map((question) =>
          question.options
            .map((o, i) => ({ i, s: o.scores[id] || 0 }))
            .sort((a, b) => b.s - a.s)[0].i);
        const verdict = selectWinner(theme, full);
        assert(verdict.winnerId === id, `full-leaning run elects ${verdict.winnerId} for ${id}`);
      }
    }
    const rate = wins / runs;
    assert(rate >= 0.5, `${id} leaning win-rate ${(rate * 100).toFixed(1)}% < 50%`);
  }
  return "12/12 reachable";
});

/* ------------------------------------------------------- 隔离检查 ---- */
check("skin.css is fully scoped and does not touch other products", () => {
  const stripped = skinCss.replace(/\/\*[\s\S]*?\*\//g, "");
  let depth = 0;
  for (const line of stripped.split("\n")) {
    const trimmed = line.trim();
    if (!trimmed) continue;
    const opens = (trimmed.match(/{/g) || []).length;
    const closes = (trimmed.match(/}/g) || []).length;
    if (trimmed.endsWith("{") && opens === 1) {
      if (!/^(body\[data-skin|@media|@keyframes|from|to|\d+%)/.test(trimmed)) {
        throw new Error(`unscoped selector: ${trimmed}`);
      }
    }
    depth += opens - closes;
  }
  assert(depth === 0, "unbalanced braces in skin.css");
  for (const foreign of ["lw-", "wx-", "pp-", "dp-", "cat-", "ggw-"]) {
    assert(!skinCss.includes(foreign), `skin.css must not reference ${foreign} (cross-product leak)`);
  }
  return "scoped, no cross-product selectors";
});

check("skin classes used by skin.js all exist in skin.css or are canonical hooks", () => {
  const js = readFileSync(join(ROOT, "deploy-ready", "themes", "greek_goddess", "skin.js"), "utf8");
  const used = new Set(
    [...js.matchAll(/class="([^"]*)"/g)].flatMap((m) => m[1].split(/\s+/))
      .flatMap((c) => c.match(/gg-[a-z0-9-]+/g) || [])
  );
  const hooks = new Set(["gg-top-right", "gg-option-text", "gg-q"]);
  const defined = new Set([...skinCss.matchAll(/\.(gg-[a-z0-9-]+)/g)].map((m) => m[1]));
  const missing = [...used].filter((c) => !defined.has(c) && !hooks.has(c));
  assert(missing.length === 0, `classes without CSS: ${missing.join(", ")}`);
  return `${used.size} classes covered`;
});

check("the skin carries no scoring, network or content-file logic", () => {
  const js = readFileSync(join(ROOT, "deploy-ready", "themes", "greek_goddess", "skin.js"), "utf8");
  for (const banned of ["normalization_bounds", "selectWinner", "quiz_content_upgrade", "fetch("]) {
    assert(!js.includes(banned), `skin must not contain ${banned}`);
  }
  return "expression only";
});

check("the skin reuses the canonical flip-card structure and motion classes", () => {
  const js = readFileSync(join(ROOT, "deploy-ready", "themes", "greek_goddess", "skin.js"), "utf8");
  for (const hook of ["flip-card", "card-arrive", "card-peek-1", "is-flipping", "art-missing"]) {
    assert(js.includes(hook), `must reuse ${hook} from the canonical motion system`);
  }
  const css = readFileSync(join(ROOT, "deploy-ready", "styles.css"), "utf8");
  for (const keyframe of ["card-arrive", "card-peek-1", "card-peek-2", "card-flip-lift"]) {
    assert(css.includes(`@keyframes ${keyframe}`), `styles.css lost ${keyframe}`);
  }
  return "canonical structure + global motion intact";
});

check("the product manifest still owns the shared greek content", () => {
  const manifest = JSON.parse(readFileSync(join(ROOT, "server", "content", "products", "greek_goddess", "product.json"), "utf8"));
  assert(manifest.product_id === "greek_goddess", "product id mismatch");
  const raw = JSON.parse(readFileSync(join(ROOT, "server", "content", "quiz_content_upgrade.json"), "utf8"));
  const theme = raw.themes.find((t) => t.id === "greek-women");
  assert(theme, "greek-women theme missing from shared content");
  assert(theme.questions.length === 24, "24 questions");
  assert(theme.results.length === 12, "12 results");
  assert(!appSource.includes("gg-"), "default templates must not reference gg- classes");
  return "own theme, shared matrix";
});

delete globalThis.__MYTHIC_SKINS__;

/* --------------------------------------------------------- 汇总 ---- */
const failures = results.filter((r) => !r.ok);
console.log("\n希腊女神（旗舰）陶绘皮肤 · 流程测试\n");
for (const r of results) console.log(`  ${r.ok ? "PASS" : "FAIL"}  ${r.name}${r.d ? " — " + r.d : ""}`);
console.log(`\n${results.length - failures.length}/${results.length} passed`);
process.exit(failures.length ? 1 : 0);

