/* 希腊女神测试 —— 产品视觉层样式（陶绘 vase 语言）
 *
 * 作用域：全部规则挂在 body[data-skin="greek_goddess"] 下，与默认模板和
 * 其他产品皮肤完全隔离。
 *
 * 世界观：陶绘（红绘/黑绘）。陶纸底带拉坯细纹、夜蓝图底、陶土点缀、刻线双框；
 * 结果卡正面 = 红绘（浅底 + 陶土人物），背面 = 黑绘（夜蓝底 + 米金文字），
 * 与 V2 视觉系统的正/背图底反转同构。卡片内部复用默认模板的
 * .flip-card/.face/.art 结构，落卡/探视/升力动效类（card-arrive 等）
 * 来自全局 styles.css，本文件只重塑颜色、字体与边框，不与之对抗。
 */

body[data-skin="greek_goddess"] {
  --gg-ink: #232E3A;          /* 夜蓝：图底与文字 */
  --gg-clay: #A6472F;         /* 陶土：红绘点缀 */
  --gg-gold: #B98A44;         /* 金赭：背面文字 */
  --gg-olive: #6B6B45;
  --gg-violet: #6E4A6B;
  --gg-paper: #F3EEE2;        /* 陶纸 */
  --gg-card: #F8F3E8;
  --gg-soft: #6E6A5E;
  --gg-hairline: rgba(35, 46, 58, 0.4);
  --gg-serif: "Songti SC", "STSong", "Noto Serif SC", "SimSun", Georgia, serif;

  margin: 0;
  color: var(--gg-ink);
  font-family: var(--gg-serif);
  background-color: var(--gg-paper);
  background-image: repeating-linear-gradient(
    0deg, transparent 0 15px, rgba(35, 46, 58, 0.028) 15px 16px);
}

body[data-skin="greek_goddess"] .gg {
  max-width: 640px;
  min-height: 100vh;
  min-height: 100dvh;
  margin: 0 auto;
  padding: 14px 16px calc(28px + env(safe-area-inset-bottom, 0px));
}

/* ---------------------------------------------------------------- 骨架 ---- */
body[data-skin="greek_goddess"] .gg-top {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 14px;
  color: var(--gg-soft);
  font-size: 12px;
  letter-spacing: .12em;
}

body[data-skin="greek_goddess"] .gg-brand {
  color: var(--gg-ink);
  font-weight: 700;
  letter-spacing: .1em;
}

body[data-skin="greek_goddess"] .gg-eyebrow {
  margin: 0 0 10px;
  color: var(--gg-clay);
  font: 600 11px/1 Georgia, serif;
  letter-spacing: .32em;
  text-transform: uppercase;
}

body[data-skin="greek_goddess"] .gg-title {
  margin: 6px 0 12px;
  font-size: clamp(22px, 6.1vw, 38px);
  font-weight: 700;
  line-height: 1.52;
  letter-spacing: .02em;
}

body[data-skin="greek_goddess"] .gg-lead {
  margin: 0 auto;
  max-width: 26em;
  color: var(--gg-soft);
  font-size: 14.5px;
  line-height: 1.95;
}

body[data-skin="greek_goddess"] .gg-foot {
  margin: 24px 0 0;
  color: #8D8672;
  font-size: 11.5px;
  line-height: 1.8;
}

/* ---------------------------------------------------------------- 卡片 ----
   刻线双框：1.5px 实线 + 3px 纸底间隔 + 1px 发丝线 */
body[data-skin="greek_goddess"] .gg-card {
  max-width: 460px;
  margin: 0 auto;
  padding: 30px 26px;
  border: 1.5px solid var(--gg-ink);
  border-radius: 2px;
  background: var(--gg-card);
  box-shadow:
    0 0 0 3px var(--gg-paper),
    0 0 0 4px var(--gg-hairline);
}

/* ---------------------------------------------------------------- 按钮 ---- */
body[data-skin="greek_goddess"] .gg-btn {
  padding: 13px 44px;
  border: 1.5px solid var(--gg-ink);
  border-radius: 2px;
  background: var(--gg-ink);
  color: #F3EEE2;
  font: 700 15.5px/1 var(--gg-serif);
  letter-spacing: .22em;
  text-indent: .22em;
  cursor: pointer;
  transition: background-color .18s ease, border-color .18s ease;
}

body[data-skin="greek_goddess"] .gg-btn:hover { background: #17202A; border-color: #17202A; }
body[data-skin="greek_goddess"] .gg-btn-big { padding: 14px 50px; font-size: 16px; }

body[data-skin="greek_goddess"] .gg-link {
  padding: 2px 0;
  border: 0;
  border-bottom: 1.5px solid rgba(35, 46, 58, .3);
  background: transparent;
  color: var(--gg-soft);
  font: 500 13px/1.5 var(--gg-serif);
  letter-spacing: .1em;
  cursor: pointer;
}

body[data-skin="greek_goddess"] .gg-link:hover { color: var(--gg-clay); border-color: var(--gg-clay); }
body[data-skin="greek_goddess"] .gg-link:disabled { opacity: .35; cursor: not-allowed; }

/* ---------------------------------------------------------------- 入场 ---- */
body[data-skin="greek_goddess"] .gg-gate { margin-top: 7vh; text-align: center; }

body[data-skin="greek_goddess"] .gg-gate-lead { margin: 0 0 22px; }

body[data-skin="greek_goddess"] .gg-gate-form { display: flex; gap: 10px; }

body[data-skin="greek_goddess"] .gg-gate-input {
  flex: 1;
  min-width: 0;
  padding: 12px 14px;
  border: 1.5px solid var(--gg-hairline);
  border-radius: 2px;
  background: #FFFDF6;
  color: var(--gg-ink);
  font: 600 14px/1.4 ui-monospace, "SF Mono", Consolas, monospace;
  letter-spacing: .06em;
}

body[data-skin="greek_goddess"] .gg-gate-input:focus-visible {
  outline: 0;
  border: 2px solid var(--gg-clay);
}

body[data-skin="greek_goddess"] .gg-gate .gg-btn { padding: 13px 30px; }

body[data-skin="greek_goddess"] .gg-gate-error {
  min-height: 20px;
  margin: 12px 0 0;
  color: var(--gg-clay);
  font-size: 13px;
}

/* ---------------------------------------------------------------- 封面 ---- */
body[data-skin="greek_goddess"] .gg-cover { margin-top: 4vh; text-align: center; }

body[data-skin="greek_goddess"] .gg-cast {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px;
  margin: 16px 0 4px;
}

body[data-skin="greek_goddess"] .gg-cast-dot {
  width: 18px;
  height: 18px;
  border-radius: 50%;
  border: 1.5px solid rgba(35, 46, 58, .35);
  transition: transform .16s ease;
}

body[data-skin="greek_goddess"] .gg-cast-dot:hover { transform: scale(1.22); border-color: var(--gg-ink); }
body[data-skin="greek_goddess"] .gg-cover-actions { margin: 22px 0 0; }

/* ---------------------------------------------------------------- 答题 ---- */
body[data-skin="greek_goddess"] .gg-progress {
  height: 6px;
  margin: 2px 2px 14px;
  border: 1px solid var(--gg-hairline);
  background:
    repeating-linear-gradient(90deg, transparent 0 13px, rgba(35, 46, 58, 0.16) 13px 14px);
  overflow: hidden;
}

body[data-skin="greek_goddess"] .gg-progress i {
  display: block;
  height: 100%;
  background: var(--gg-clay);
  transition: width .3s ease;
}

body[data-skin="greek_goddess"] .gg-q-count {
  margin: 0 0 6px;
  color: var(--gg-soft);
  font: 700 12px/1 Georgia, serif;
  letter-spacing: .24em;
}

body[data-skin="greek_goddess"] .gg-q-text {
  margin: 0 0 12px;
  padding: 16px 18px;
  border: 1.5px solid var(--gg-ink);
  border-radius: 2px;
  background: var(--gg-card);
  box-shadow: 0 0 0 3px var(--gg-paper), 0 0 0 4px var(--gg-hairline);
  font-size: clamp(20px, 5.4vw, 26px);
  font-weight: 700;
  line-height: 1.62;
}

body[data-skin="greek_goddess"] .gg-options { display: grid; gap: 10px; }

body[data-skin="greek_goddess"] .gg-option {
  display: flex;
  gap: 12px;
  align-items: center;
  padding: 12px 15px;
  border: 1.5px solid var(--gg-hairline);
  border-radius: 2px;
  background: var(--gg-card);
  color: var(--gg-ink);
  font: 400 15px/1.68 var(--gg-serif);
  text-align: left;
  cursor: pointer;
  transition: border-color .16s ease, background-color .16s ease;
  animation: gg-rise .4s cubic-bezier(.2, .7, .2, 1) both;
}

body[data-skin="greek_goddess"] .gg-option:nth-child(2) { animation-delay: .06s; }
body[data-skin="greek_goddess"] .gg-option:nth-child(3) { animation-delay: .12s; }

body[data-skin="greek_goddess"] .gg-option:hover { border-color: var(--gg-clay); }

body[data-skin="greek_goddess"] .gg-option-key {
  display: grid;
  flex: 0 0 28px;
  width: 28px;
  height: 28px;
  place-items: center;
  border: 1.5px solid var(--gg-hairline);
  border-radius: 2px;
  color: var(--gg-soft);
  font: 700 12.5px/1 Georgia, serif;
}

body[data-skin="greek_goddess"] .gg-option.picked {
  border-color: var(--gg-clay);
  background: color-mix(in srgb, var(--gg-clay) 8%, var(--gg-card));
}

body[data-skin="greek_goddess"] .gg-option.picked .gg-option-key {
  border-color: var(--gg-clay);
  background: var(--gg-clay);
  color: #F3EEE2;
}

@keyframes gg-rise {
  0% { opacity: 0; transform: translateY(8px); }
  100% { opacity: 1; transform: translateY(0); }
}

body[data-skin="greek_goddess"] .gg-q-nav {
  display: flex;
  justify-content: space-between;
  margin-top: 12px;
}

/* ---------------------------------------------------------------- 等待 ---- */
body[data-skin="greek_goddess"] .gg-loading { margin-top: 10vh; text-align: center; }

body[data-skin="greek_goddess"] .gg-loading-text {
  margin: 8px 0 4px;
  font-weight: 700;
  font-size: 16px;
  letter-spacing: .16em;
}

/* ---------------------------------------------------------------- 结果 ----
   卡片内部复用默认模板结构（.flip-card/.face/.art/.body）以继承翻面与
   CARD_MOTION 动效；此处只做陶绘重塑。 */

body[data-skin="greek_goddess"] .gg-result { margin-top: 1vh; }

body[data-skin="greek_goddess"] .gg-result .scene { margin: 0 0 4px; }

/* 外壳零装饰：面旋转时底下不许有不动的框。阴影挂在 .face 上，随面一起转。
   高度由 skin.js 按两面内容的较高者设定（正典的 660px 固定高在短文案下会露出
   填充块）；正/背 face 背景色各随其面，fill 区域无缝。 */
body[data-skin="greek_goddess"] .gg-result .flip-card {
  border: 0;
  border-radius: 0;
  padding: 0;
  background: transparent;
  box-shadow: none;
  min-height: 0;
}

body[data-skin="greek_goddess"] .gg-result .flip-card .face {
  border-radius: 2px;
  overflow: hidden;
  background: var(--gg-card);
  box-shadow: 0 14px 30px rgba(35, 46, 58, 0.18);
}

body[data-skin="greek_goddess"] .gg-result .flip-card .art {
  border: 0;
  border-bottom: 1.5px solid var(--gg-hairline);
  border-radius: 0;
  background: #EFE7D6;
}

body[data-skin="greek_goddess"] .gg-result .flip-card .body { padding: 18px 22px 16px; }

/* 正面 = 红绘：浅底、陶土点缀 */
body[data-skin="greek_goddess"] .gg-result .face.front .body { background: transparent; }
body[data-skin="greek_goddess"] .gg-result .face.front .eyebrow {
  color: var(--gg-ink);
  font: 700 26px/1.15 var(--gg-serif);
}
body[data-skin="greek_goddess"] .gg-result .face.front .eyebrow small {
  color: var(--gg-soft);
  font: 400 14px/1 Georgia, serif;
  letter-spacing: .05em;
}
body[data-skin="greek_goddess"] .gg-result .face.front h2 { color: var(--gg-clay); }
body[data-skin="greek_goddess"] .gg-result .face.front .reading { color: #514A3E; }

/* 解读风格切换：三档小字签注，占一行，不抢卡面 */
body[data-skin="greek_goddess"] .gg-modes {
  display: flex;
  justify-content: center;
  gap: 18px;
  margin: 2px 0 8px;
}

body[data-skin="greek_goddess"] .gg-mode {
  padding: 2px 1px;
  border: 0;
  border-bottom: 1.5px solid transparent;
  background: transparent;
  color: var(--gg-soft);
  font: 500 12.5px/1.4 var(--gg-serif);
  letter-spacing: .2em;
  cursor: pointer;
  transition: color .15s ease, border-color .15s ease;
}

body[data-skin="greek_goddess"] .gg-mode:hover { color: var(--gg-ink); }

body[data-skin="greek_goddess"] .gg-mode.active {
  color: var(--gg-clay);
  border-bottom-color: var(--gg-clay);
}

/* 背面 = 黑绘：夜蓝底、米金文字 */
body[data-skin="greek_goddess"] .gg-result .face.back .body { background: var(--gg-ink); }
body[data-skin="greek_goddess"] .gg-result .face.back .eyebrow { color: #E8DCC8; font: 700 26px/1.15 var(--gg-serif); }
body[data-skin="greek_goddess"] .gg-result .face.back .eyebrow small { color: var(--gg-gold); font: 400 14px/1 Georgia, serif; }
body[data-skin="greek_goddess"] .gg-result .face.back h2 { color: #C98B72; }
body[data-skin="greek_goddess"] .gg-result .face.back .reading { color: #D8CCB8; }
body[data-skin="greek_goddess"] .gg-result .flip-card .back .art { background: #1B242E; }

/* 兜底美术：刻线希腊字母 */
body[data-skin="greek_goddess"] .gg-fallback {
  display: grid;
  place-items: center;
  width: 100%;
  height: 100%;
  min-height: 180px;
  color: var(--gg-clay);
  background:
    linear-gradient(transparent 0 38%, rgba(35, 46, 58, .12) 38% calc(38% + 1.5px), transparent calc(38% + 1.5px));
}

body[data-skin="greek_goddess"] .gg-fallback span {
  font: 700 74px/1 Georgia, serif;
  letter-spacing: .06em;
}

body[data-skin="greek_goddess"] .gg-result .flip-card .face.art-missing .art .gg-fallback span {
  color: var(--gg-clay);
}

body[data-skin="greek_goddess"] .gg-result .flip-card .back .art .gg-fallback span { color: var(--gg-gold); }

/* 卡下的动作区与免责 */
body[data-skin="greek_goddess"] .gg-save {
  margin: 16px 0 0;
  text-align: center;
}

body[data-skin="greek_goddess"] .gg-save .gg-btn { padding: 13px 42px; font-size: 15px; }

body[data-skin="greek_goddess"] .gg-minor {
  display: flex;
  justify-content: center;
  gap: 22px;
  margin-top: 8px;
}

body[data-skin="greek_goddess"] .gg-disclaimer {
  margin: 18px 0 0;
