  body[data-skin="greek_goddess"] .gg-option { animation: none; }
  body[data-skin="greek_goddess"] .gg-option,
  body[data-skin="greek_goddess"] .gg-cast-dot,
  body[data-skin="greek_goddess"] .gg-progress i { transition: none; }
}

