function resultFace(result, en, side, subtitle, reading) {
  const label = `${result.id || "女神"} ${side === "front" ? "正面" : "背面"}艺术图`;
  /* 解读风格层：文学（正典）/ 冷读 / 占卜。只在正面出现；没有变体的主题自动隐藏。 */
