readFileState.content:
/* 希腊女神测试 —— 产品视觉层（product skin，陶绘语言）
 *
 * 世界观：陶绘（红绘/黑绘）。陶纸底、夜蓝图底、陶土点缀、刻线双框；
 * 结果卡复用默认模板的 .flip-card/.face 结构与全局 CARD_MOTION 动效类，
 * 翻面/探视/落卡行为在此移植（与 app.js bindResultCard 行为一致），
 * 正面红绘浅底、背面黑绘夜蓝。
 * 皮肤只做表达：评分、题库、网络一律不进本文件。
 */

const SKIN_ID = "greek_goddess";
const THEME = "greek-women";

const esc = (value) =>
  String(value ?? "").replace(/[&<>"']/g, (ch) => (
    { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[ch]
  ));

const CAST = [
  { id: "athena", en: "Athena", color: "#344A68" },
  { id: "aphrodite", en: "Aphrodite", color: "#944A60" },
  { id: "artemis", en: "Artemis", color: "#4A5A3A" },
  { id: "hecate", en: "Hecate", color: "#101628" },
  { id: "persephone", en: "Persephone", color: "#5A2A42" },
  { id: "demeter", en: "Demeter", color: "#8C6024" },
  { id: "medea", en: "Medea", color: "#401826" },
  { id: "atalanta", en: "Atalanta", color: "#606832" },
  { id: "hera", en: "Hera", color: "#22304A" },
  { id: "hestia", en: "Hestia", color: "#964A14" },
  { id: "nike", en: "Nike", color: "#4E5A28" },
  { id: "circe", en: "Circe", color: "#4E305C" },
];

const GREEK_LETTER = {
  athena: "Α", aphrodite: "Α", artemis: "Α", hecate: "Ε",
  persephone: "Π", demeter: "Δ", medea: "Μ", atalanta: "Α",
  hera: "Η", hestia: "Ε", nike: "Ν", circe: "Κ",
};

const colorOf = (result) => {
  const cast = CAST.find((c) => c.id === (result && result.id));
  return (cast && cast.color) || "#232E3A";
};

function pageShell(inner) {
  return `<div class="gg">${inner}</div>`;
}

function brandBar(right) {
  return `<header class="gg-top"><span class="gg-brand">MYTHIC · 希腊女神</span><span class="gg-top-right">${right}</span></header>`;
}

/* ----------------------------------------------------------- 回执 ---- */
const GATE_ERRORS = {
  empty: "先输入兑换码。",
  already_bound: "这个码已在别的浏览器激活。换设备请联系卖家重置绑定。",
  rate_limited: "尝试太频繁了，稍等一分钟再来。",
  invalid: "兑换码无效，检查一下再试。",
};

function gateView(ctx) {
  const html = pageShell(`
    ${brandBar("入口")}
    <section class="gg-card gg-gate">
      <p class="gg-eyebrow">Mythic · Greek Goddesses</p>
      <h1 class="gg-title">凭码入场</h1>
      <p class="gg-lead gg-gate-lead">输入兑换码开始。激活后与当前浏览器绑定，之后随时回来。</p>
      <div class="gg-gate-form">
        <input id="gg-gate-code" class="gg-gate-input" type="text" autocomplete="off"
               autocapitalize="characters" spellcheck="false" placeholder="MYTHIC-XXXXX-XXXXX" aria-label="兑换码">
        <button class="gg-btn" id="gg-gate-submit">开始</button>
      </div>
      <p class="gg-gate-error" id="gg-gate-error" role="alert">${esc(ctx.message || "")}</p>
      <p class="gg-foot">兑换码在小红书店铺购买后获得。更换浏览器或清除数据后需重新激活，届时可联系卖家重置。</p>
    </section>`);
  const bind = (root) => {
    const input = root.querySelector("#gg-gate-code");
    const submit = root.querySelector("#gg-gate-submit");
    const error = root.querySelector("#gg-gate-error");
    const show = (text) => { error.textContent = text; };
    const run = async () => {
      const outcome = await ctx.submit(input.value);
      if (outcome.type === "unlocked") return;
      if (outcome.type === "other-product") {
        show(`这个码属于《${outcome.name}》，请打开对应测试的网址使用。`);
        return;
      }
      show(GATE_ERRORS[outcome.kind] || "兑换码无效，检查一下再试。");
      input.focus();
    };
    submit.addEventListener("click", run);
    input.addEventListener("keydown", (event) => {
      if (event.key === "Enter") { event.preventDefault(); run(); }
    });
  };
  return { html, bind };
}

/* ----------------------------------------------------------- 封面 ---- */
function coverView(ctx) {
  const html = pageShell(`
    ${brandBar("入口")}
    <section class="gg-card gg-cover">
      <p class="gg-eyebrow">Greek Goddesses · 12 Archetypes</p>
      <h1 class="gg-title">你与哪位希腊神话女性，<br>共享一段心事？</h1>
      <p class="gg-lead">${esc(ctx.theme.subtitle || "24 个生活片刻 · 12 位女性神话原型")}</p>
      <div class="gg-cast" aria-label="十二位女神">
        ${CAST.map((c) => `<span class="gg-cast-dot" style="background:${c.color}" title="${esc(c.en)}"></span>`).join("")}
      </div>
      <div class="gg-cover-actions">
        <button class="gg-btn gg-btn-big" id="gg-start">开始</button>
      </div>
      <p class="gg-foot">24 个生活片刻 · 约八分钟 · 原创娱乐测试，不是科学人格测评</p>
    </section>`);
  const bind = (root) => {
    root.querySelector("#gg-start").addEventListener("click", () => ctx.start());
  };
  return { html, bind };
}

/* ----------------------------------------------------------- 答题 ---- */
function questionView(ctx) {
  const buttons = ctx.options.map((text, i) => `
    <button class="gg-option${ctx.selected === i ? " picked" : ""}" data-i="${i}" aria-pressed="${ctx.selected === i}">
      <span class="gg-option-key" aria-hidden="true">${"ABC"[i] || "•"}</span>
      <span class="gg-option-text">${esc(text)}</span>
    </button>`).join("");

  const html = pageShell(`
    ${brandBar(`${String(ctx.index + 1).padStart(2, "0")} / ${ctx.total}`)}
    <div class="gg-progress" role="progressbar" aria-label="答题进度" aria-valuemin="1" aria-valuemax="${ctx.total}" aria-valuenow="${ctx.index + 1}">
      <i style="width:${Math.round(((ctx.index + 1) / ctx.total) * 100)}%"></i>
    </div>
    <section class="gg-q">
      <p class="gg-q-count">QUESTION ${String(ctx.index + 1).padStart(2, "0")} / ${ctx.total}</p>
      <h2 class="gg-q-text">${esc(ctx.question)}</h2>
      <div class="gg-options">${buttons}</div>
      <div class="gg-q-nav">
        <button class="gg-link" id="gg-prev" ${ctx.index === 0 ? "disabled" : ""}>← 上一题</button>
        <button class="gg-link" id="gg-exit">返回主题</button>
      </div>
    </section>`);

  const bind = (root) => {
    let advanced = false;
    root.querySelectorAll(".gg-option").forEach((option) => {
      option.addEventListener("click", () => {
        if (advanced) return;
        advanced = true;
        option.classList.add("picked");
        option.setAttribute("aria-pressed", "true");
        window.setTimeout(() => ctx.select(Number(option.dataset.i)), 260);
      });
    });
    const prev = root.querySelector("#gg-prev");
    if (prev) prev.addEventListener("click", () => { if (!advanced) ctx.previous(); });
    root.querySelector("#gg-exit").addEventListener("click", () => { if (!advanced) ctx.exit(); });
  };
  return { html, bind };
}

/* --------------------------------------------------------- 等待 ---- */
function resultLoadingView() {
  const html = pageShell(`
    ${brandBar("陶轮转动中")}
    <section class="gg-card gg-loading">
      <p class="gg-eyebrow">Kiln</p>
      <p class="gg-loading-text">正在烧制你的这一张……</p>
      <p class="gg-foot">判定在服务端完成。</p>
    </section>`);
  return { html };
}

/* ----------------------------------------------------------- 结果 ----
   卡片结构与默认模板同构（.scene/.flip-card/.face/.art/.body），
   因此继承全局 styles.css 的翻面 3D 与 CARD_MOTION 动效（含每位一缕风）。 */

function faceArt(resultId, side, label) {
  const src = `/assets/${THEME}/${encodeURIComponent(resultId)}-${side}.webp`;
  const letter = GREEK_LETTER[resultId] || "✦";
  return `<figure class="art">
    <img src="${src}" alt="${esc(label)}" draggable="false" decoding="async" data-art>
    <div class="flip-fallback" data-art-fallback hidden><div class="gg-fallback" aria-hidden="true"><span>${letter}</span></div></div>
  </figure>`;
}

/* 解读风格组件：数据驱动——结果对象上有什么 reading_* 字段就渲染什么档位。
   标签查表可扩展（catalog: factory/components/interpretation-styles.json），
   未注册的 id 退回显示 id 本身。 */
const STYLE_LABELS = { literary: "文学", cold: "冷读", oracle: "占卜", manual: "说明书", letter: "信件" };

function styleEntries(result) {
  const entries = [];
  if (result.reading) entries.push(["literary", STYLE_LABELS.literary, result.reading]);
  Object.keys(result)
    .filter((k) => k.startsWith("reading_") && typeof result[k] === "string" && result[k])
    .forEach((k) => {
      const id = k.slice("reading_".length);
      entries.push([id, STYLE_LABELS[id] || id, result[k]]);
    });
  return entries;
}

function resultFace(result, en, side, subtitle, reading, modesHtml) {
  const label = `${result.id || "女神"} ${side === "front" ? "正面" : "背面"}艺术图`;
  return `<section class="face ${side}">
    ${faceArt(result.id, side, label)}
    <div class="body">
      <div class="eyebrow">${esc(result.name || "此刻的你")}${en ? `<small>${esc(en)}</small>` : ""}</div>
      <h2>${esc(subtitle || "")}</h2>
      ${modesHtml || ""}
      <p class="reading">${esc(reading || "")}</p>
    </div>
  </section>`;
}

function verdictView(ctx) {
  const result = ctx.result || {};
  const id = result.id || "generic";
  const en = (CAST.find((c) => c.id === result.id) || {}).en || "";
  const frontSubtitle = result.subtitle || result.core_energy || "";
  const frontReading = result.reading || result.description || "";
  const backSubtitle = result.back_subtitle || frontSubtitle;
  const backReading = result.back_reading || frontReading;
  const entries = styleEntries(result);
  const hasModes = entries.length > 1;
  const modesHtml = hasModes
    ? `<div class="gg-modes" role="group" aria-label="解读风格">${entries
      .map(([mode, modeLabel], i) => `<button class="gg-mode${i === 0 ? " active" : ""}" data-mode="${esc(mode)}" aria-pressed="${i === 0}">${esc(modeLabel)}</button>`)
      .join("")}</div>`
    : "";

  const html = pageShell(`
    ${brandBar("这一张")}
    <section class="gg-result" style="--gg-accent:${colorOf(result)}">
      <div class="scene">
        <article class="result-panel result-card flip-card result-${esc(id)}" data-result-id="${esc(id)}" data-result-art="${esc(id)}" role="button" tabindex="0" aria-label="翻转${esc(result.name || "")}结果卡" aria-pressed="false">
          ${resultFace(result, en, "front", frontSubtitle, frontReading, modesHtml)}
          ${resultFace(result, en, "back", backSubtitle, backReading, "")}
        </article>
      </div>
      <div class="gg-save">
        <button class="gg-btn" id="gg-share">生成分享图</button>
        <div class="gg-minor">
          <button class="gg-link" id="gg-copy">复制文案</button>
          <button class="gg-link" id="gg-again">再测一次</button>
          <button class="gg-link" id="gg-home">返回主题</button>
        </div>
      </div>
      <p class="gg-disclaimer">This is a cultural character-style experience, not a scientific personality assessment.</p>
    </section>`);

  const bind = (root) => {
    /* 缺图兜底：每面独立降级到刻线希腊字母，不出现破图。 */
    root.querySelectorAll("[data-art]").forEach((img) => {
      img.addEventListener("error", () => {
        const face = img.closest(".face");
        if (!face) return;
        face.classList.add("art-missing");
        img.remove();
        const fallback = face.querySelector("[data-art-fallback]");
        if (fallback) fallback.hidden = false;
      });
    });

    /* 翻面 + CARD_MOTION：落卡、两次探视、升力。与默认模板行为一致：
       邀请最多两次之后永远安静；计时器只在真实浏览器排程。 */
    const card = root.querySelector("[data-result-art]");
    const frontFace = card.querySelector(".front");
    const backFace = card.querySelector(".back");
    const media = typeof window.matchMedia === "function"
      ? window.matchMedia("(prefers-reduced-motion: reduce)") : null;
    const reduceMotion = Boolean(media && media.matches);
    if (Array.isArray(window.__ggCardMotionTimers)) window.__ggCardMotionTimers.forEach(window.clearTimeout);
    window.__ggCardMotionTimers = [];
    const timers = window.__ggCardMotionTimers;

    if (!reduceMotion) {
      card.classList.add("card-arrive");
      card.addEventListener("animationend", function onArrive(event) {
        if (event.animationName !== "card-arrive") return;
        card.classList.remove("card-arrive");
        card.removeEventListener("animationend", onArrive);
      });
    }

    let touched = false;
    const quietInvite = () => {
      touched = true;
      timers.forEach(window.clearTimeout);
    };

    if (media && !reduceMotion) {
      timers.push(window.setTimeout(() => {
        if (touched || !card.isConnected) return;
        card.classList.add("card-peek-1");
      }, 3000));
      timers.push(window.setTimeout(() => {
        if (touched || !card.isConnected) return;
        card.classList.remove("card-peek-1");
        card.classList.add("card-peek-2");
      }, 7500));
    }

    const toggle = () => {
      const isBack = card.classList.toggle("is-back");
      card.setAttribute("aria-pressed", String(isBack));
      card.setAttribute("aria-label", isBack ? "返回结果卡正面" : "翻转结果卡");
      if (frontFace) frontFace.setAttribute("aria-hidden", String(isBack));
      if (backFace) backFace.setAttribute("aria-hidden", String(!isBack));
      if (!touched) quietInvite();
      card.classList.remove("card-peek-1");
      card.classList.remove("card-peek-2");
      card.classList.remove("is-flipping");
      void card.offsetWidth; /* 连续翻面时让升力动画各自重新起步 */
      if (!reduceMotion) card.classList.add("is-flipping");
    };
    card.onclick = toggle;
    card.onkeydown = (event) => {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        toggle();
      }
    };

    /* 卡高 = 两面内容的较高者（faces 绝对定位，容器需要显式高度；
       正典的 660px 固定高在短文案下会露出填充块）。切风格后重算。 */
    const fitCard = () => {
      card.style.height = "0px";
      const target = Math.max(
        Number(frontFace?.scrollHeight) || 0,
        Number(backFace?.scrollHeight) || 0
      );
      if (target > 0) card.style.height = `${target}px`;
    };
    fitCard();
    if (typeof window !== "undefined" && typeof window.requestAnimationFrame === "function") {
      window.requestAnimationFrame(fitCard); /* 图首帧布局后二次校准 */
    }

    /* 解读风格切换：换正面 reading 文本。stopPropagation 防止触发翻面。
       档位由 entries 数据驱动（brief 声明的风格集）。 */
    const frontReading = card.querySelector(".face.front .reading");
    const modeButtons = [...card.querySelectorAll(".gg-mode")];
    if (frontReading && modeButtons.length > 1) {
      const variants = Object.fromEntries(entries.map(([mode, , text]) => [mode, text]));
      modeButtons.forEach((btn) => {
        btn.addEventListener("click", (event) => {
          event.stopPropagation();
          const text = variants[btn.dataset.mode];
          if (!text) return;
          modeButtons.forEach((other) => {
            other.classList.toggle("active", other === btn);
            other.setAttribute("aria-pressed", String(other === btn));
          });
          frontReading.textContent = text;
          fitCard();
        });
      });
    }

    /* 动作区 */
    const copy = root.querySelector("#gg-copy");
    copy.addEventListener("click", async () => {
      await ctx.actions.copy();
      copy.textContent = "已复制 ✓";
      window.setTimeout(() => { copy.textContent = "复制文案"; }, 1800);
    });
    root.querySelector("#gg-share").addEventListener("click", () => ctx.actions.share());
    root.querySelector("#gg-again").addEventListener("click", () => ctx.actions.again());
    root.querySelector("#gg-home").addEventListener("click", () => ctx.actions.home());
  };
  return { html, bind };
}

/* -------------------------------------------------------- 分享结果图 ---- */
function drawShareImage({ result }) {
  const canvas = document.createElement("canvas");
  canvas.width = 900;
  canvas.height = 1200;
  const c = canvas.getContext("2d");
  const accent = colorOf(result);

  const paper = (withFrame) => {
    c.fillStyle = "#F3EEE2";
    c.fillRect(0, 0, 900, 1200);
    c.strokeStyle = "#232E3A";
    c.lineWidth = 5;
    c.strokeRect(42, 42, 816, 1116);
    c.lineWidth = 2;
    c.strokeStyle = "rgba(35, 46, 58, 0.4)";
    c.strokeRect(60, 60, 780, 1080);
    if (withFrame) {
      c.fillStyle = "#A6472F";
      [[74, 74], [826, 74], [74, 1126], [826, 1126]].forEach(([x, y]) => {
        c.beginPath(); c.arc(x, y, 5, 0, Math.PI * 2); c.fill();
      });
    }
  };

  const center = (text, y, font, color) => {
    c.font = font;
    c.fillStyle = color;
    c.textAlign = "center";
    c.fillText(text, 450, y);
  };

  paper(true);
  center("MYTHIC · 希腊女神测试", 128, "600 28px 'PingFang SC', 'Microsoft YaHei', sans-serif", "#6E6A5E");

  const img = new Image();
  img.onload = () => {
    const w = 470;
    const h = (img.height / img.width) * w;
    const x = (900 - w) / 2;
    const y = 170;
    c.save();
    c.strokeStyle = "#232E3A";
    c.lineWidth = 4;
    c.strokeRect(x - 6, y - 6, w + 12, h + 12);
    c.drawImage(img, x, y, w, h);
    c.restore();
    finish(y + h + 96);
  };
  img.onerror = () => finish(560);

  function finish(top) {
    const en = (CAST.find((cast) => cast.id === result.id) || {}).en || "";
    center(result.name || "", top, "800 76px 'Songti SC', 'PingFang SC', sans-serif", accent);
    if (en) center(en, top + 44, "400 26px Georgia, serif", "#6E6A5E");
    const line = result.share_line || result.subtitle || "";
    c.font = "600 36px 'PingFang SC', 'Microsoft YaHei', sans-serif";
    c.fillStyle = "#232E3A";
    c.textAlign = "center";
    const rows = wrap(c, line, 660);
    rows.forEach((rowText, i) => c.fillText(rowText, 450, top + 108 + i * 54));

    CAST.forEach((cast, i) => {
      c.fillStyle = cast.color;
      c.beginPath();
      c.arc(450 - (CAST.length - 1) * 13 + i * 26, 1080, 6, 0, Math.PI * 2);
      c.fill();
    });
    center("结果由答题选择生成 · 原创演绎，非神话立场 · 非科学人格测评", 1130, "300 22px 'PingFang SC', 'Microsoft YaHei', sans-serif", "#8D8672");

    canvas.toBlob((blob) => {
      if (!blob) return;
      const link = document.createElement("a");
      link.download = `greek-${result.id || "result"}.png`;
      link.href = URL.createObjectURL(blob);
      link.click();
      window.setTimeout(() => URL.revokeObjectURL(link.href), 1000);
    }, "image/png");
  }
}

function wrap(c, text, maxWidth) {
  const rows = [];
  let current = "";
  for (const ch of String(text || "")) {
    if (c.measureText(current + ch).width > maxWidth) { rows.push(current); current = ch; }
    else current += ch;
  }
  if (current) rows.push(current);
  return rows;
}

export default {
  id: SKIN_ID,
  title: "你与哪位希腊神话女性，共享一段心事？",
  copyText(result) {
    return `${result.name || ""}\n${result.share_line || result.reading || ""}\n\n来自「希腊女神测试」原创互动测试`;
  },
  share({ result }) {
    if (typeof document === "undefined") return;
    drawShareImage({ result });
  },
  views: {
    gate: gateView,
    cover: coverView,
    question: questionView,
    resultLoading: resultLoadingView,
    result: verdictView,
  },
};

