// factory/studio/server.mjs — 工厂下单台（本地工具，仅 127.0.0.1）。
//
//   MYTHIC_STUDIO_PORT=8795 node factory/studio/server.mjs
//
// 职责（有意保持最小）：
//   GET  /              下单表单页（factory/studio/index.html）
//   GET  /api/catalog   解读风格 catalog + custom-lite 预设视觉族（表单数据源）
//   POST /api/check     组装 brief → create-test.mjs --check（干跑，不建目录）
//   POST /api/create    brief 存入 factory/orders/ → 真实 create-test → 返回文件树与 STATUS
//
// 生产仍按 STATUS.md 协议交给 agent；本工具替代的是需求沟通与立项文档。
import { createServer } from "node:http";
import { spawnSync } from "node:child_process";
import { readFileSync, writeFileSync, existsSync, readdirSync, statSync } from "node:fs";
import { join, dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const HERE = dirname(fileURLToPath(import.meta.url));
const FACTORY = resolve(HERE, "..");
const REPO = resolve(FACTORY, "..");
const PORT = Number(process.env.MYTHIC_STUDIO_PORT || 8795);
const HOST = "127.0.0.1";

const CATALOG = JSON.parse(readFileSync(join(FACTORY, "components", "interpretation-styles.json"), "utf8"));
const PROFILE = JSON.parse(readFileSync(join(FACTORY, "profiles", "custom-lite.json"), "utf8"));

const json = (res, status, body) => {
  res.writeHead(status, { "Content-Type": "application/json; charset=utf-8", "Cache-Control": "no-store" });
  res.end(JSON.stringify(body));
};

const ID_PATTERN = /^[a-z][a-z0-9_-]{2,39}$/;

function buildBrief(body) {
  const product_id = String(body.product_id || "").trim();
  if (!ID_PATTERN.test(product_id)) return { error: "product_id 需要匹配 ^[a-z][a-z0-9_-]{2,39}$（小写字母开头，3–40 位）" };
  const question_count = Number(body.question_count);
  const result_count = Number(body.result_count);
  if (!Number.isInteger(question_count) || question_count < 12 || question_count > 16) {
    return { error: "custom-lite 围栏：题量 12–16" };
  }
  if (!Number.isInteger(result_count) || result_count < 6 || result_count > 8) {
    return { error: "custom-lite 围栏：结果数 6–8" };
  }
  const styles = Array.isArray(body.interpretation_styles) ? body.interpretation_styles.filter((s) => s !== "literary") : [];
  const KNOWN = new Set(CATALOG.styles.map((s) => s.id));
  const unknown = styles.filter((s) => !KNOWN.has(s));
  if (unknown.length) return { error: `未注册的解读风格: ${unknown.join(", ")}` };

  return {
    brief: {
      product_id,
      title: String(body.title || "").slice(0, 60),
      theme: product_id,
      audience: String(body.audience || "").slice(0, 300),
      tone: (Array.isArray(body.tone) ? body.tone : []).map((t) => String(t).slice(0, 30)).filter(Boolean).slice(0, 8),
      question_count,
      result_count,
      result_style: "archetype",
      visual_direction: String(body.visual_direction || "").slice(0, 500),
      image_required: false,
      interpretation_styles: ["literary", ...styles],
      commercial_mode: "custom_private",
      owner_id: String(body.owner_id || "demo-customer").slice(0, 40),
      language: "zh-CN",
      created_for: String(body.owner_id || "demo-customer").slice(0, 120),
      notes: [
        "来源：工厂下单台（factory/studio/）。",
        "素材边界：选题灵感为公共领域意象，结果原型、题目、文案、视觉全原创，不引用任何作品文本或他人测试。",
        "差异化与推广钩子（≥3 条）由 S1 立项补全。",
      ].join("\n"),
      price_hint: null,
      revenue_share_hint: null,
      status: "draft",
    },
  };
}

function runCreateTest(args) {
  const r = spawnSync(process.execPath, [join(FACTORY, "create-test.mjs"), ...args], {
    cwd: REPO,
    encoding: "utf8",
    timeout: 30000,
  });
  return { code: r.status ?? -1, stdout: (r.stdout || "").trim(), stderr: (r.stderr || "").trim() };
}

function fileTree(dir, prefix = "") {
  const out = [];
  for (const name of readdirSync(dir).sort()) {
    const p = join(dir, name);
    const st = statSync(p);
    if (st.isDirectory()) out.push(...fileTree(p, `${prefix}${name}/`));
    else out.push({ file: `${prefix}${name}`, bytes: st.size });
  }
  return out;
}

const server = createServer((req, res) => {
  const url = new URL(req.url, `http://${HOST}:${PORT}`);
  if (req.method === "GET" && (url.pathname === "/" || url.pathname === "/index.html")) {
    res.writeHead(200, { "Content-Type": "text/html; charset=utf-8" });
    return res.end(readFileSync(join(HERE, "index.html")));
  }
  if (req.method === "GET" && url.pathname === "/api/catalog") {
    return json(res, 200, {
      styles: CATALOG.styles.map(({ id, name, tone, length }) => ({ id, name, tone, length })),
      visual_families: PROFILE.constraints.visual.preset_visual_families,
      fences: {
        question_count: PROFILE.constraints.question_count,
        result_count: PROFILE.constraints.result_count,
      },
    });
  }

  let body = "";
  req.on("data", (c) => { body += c; if (body.length > 64 * 1024) req.destroy(); });
  req.on("end", () => {
    let input = {};
    try { input = JSON.parse(body || "{}"); } catch { return json(res, 400, { ok: false, error: "bad_json" }); }

    if (req.method === "POST" && url.pathname === "/api/check") {
      const built = buildBrief(input);
      if (built.error) return json(res, 400, { ok: false, error: built.error });
      const tmp = join(FACTORY, "orders", `.probe-${Date.now()}.json`);
      writeFileSync(tmp, JSON.stringify(built.brief, null, 2));
      const r = runCreateTest(["--check", tmp]);
      return json(res, 200, { ok: r.code === 0, output: r.stdout || r.stderr });
    }

    if (req.method === "POST" && url.pathname === "/api/create") {
      const built = buildBrief(input);
      if (built.error) return json(res, 400, { ok: false, error: built.error });
      const briefPath = join(FACTORY, "orders", `${built.brief.product_id}.brief.json`);
      if (existsSync(briefPath) && !input.overwrite) {
        return json(res, 409, { ok: false, error: `订单已存在: factory/orders/${built.brief.product_id}.brief.json（换 product_id，或带 overwrite 重跑）` });
      }
      const workDir = join(FACTORY, "work", built.brief.product_id);
      if (existsSync(workDir)) {
        return json(res, 409, { ok: false, error: `工作目录已存在: factory/work/${built.brief.product_id}（防覆盖；重开请先归档改名）` });
      }
      writeFileSync(briefPath, JSON.stringify(built.brief, null, 2) + "\n");
      const r = runCreateTest([briefPath]);
      if (r.code !== 0) return json(res, 500, { ok: false, error: "create-test 失败", output: r.stdout + "\n" + r.stderr });
      const statusPath = join(workDir, "STATUS.md");
      return json(res, 200, {
        ok: true,
        brief_path: `factory/orders/${built.brief.product_id}.brief.json`,
        work_dir: `factory/work/${built.brief.product_id}/`,
        files: fileTree(workDir),
        status_md: readFileSync(statusPath, "utf8"),
        next: `把 factory/work/${built.brief.product_id}/STATUS.md 交给生产 agent：按协议读 INTERNAL_TEST_FACTORY skill → S1→S5，质量门全过即成品。`,
      });
    }

    json(res, 404, { ok: false, error: "not_found" });
  });
});

server.listen(PORT, HOST, () => {
  console.log(`[studio] 工厂下单台 on http://${HOST}:${PORT}`);
});

