const CN = { title: "主题", product_id: "产品 ID", audience: "想测什么", tone: "语调标签", visual_direction: "视觉方向" };
const err = (id) => { const el = $(id); el.classList.add("err"); el.addEventListener("input", () => el.classList.remove("err"), { once: true }); };

function validate() {
  const f = form();
  const missing = [];
  const need = (id, ok, why) => { if (!ok) { err(id); missing.push(`${CN[id]}：${why}`); } };
  need("title", f.title.length >= 2, "一句话主题还没填");
  need("product_id", /^[a-z][a-z0-9_-]{2,39}$/.test(f.product_id), "小写字母开头，3–40 位（主题输入后会自动生成）");
  need("audience", f.audience.length >= 4, "给谁玩、测什么、什么场合，至少写一句");
  need("tone", f.tone.length >= 1, "至少一个语调标签（逗号分隔）");
  need("visual_direction", f.visual_direction.length >= 4, "从下拉选一个画风即可自动带出");
  return missing;
}

function friendly(text) {
  return String(text)
    .replace(/brief\.(\w+)/g, (m, k) => CN[k] || k)
    .replace(/长度 0 < minLength 4/g, "还没填")
    .replace(/长度 0 < minLength 2/g, "还没填")
    .replace(/0 项 < minItems 1/g, "至少要一个")
    .replace(/项 < minItems/g, "项不足，最少");
}

async function doCheck() {
  const missing = validate();
  if (missing.length) { show("还差这几项：\n· " + missing.join("\n· "), "bad"); return; }
  show("校验中…");
  const r = await fetch("/api/check", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(form()) });
  const d = await r.json();
  show(friendly(d.output || d.error || "无输出"), d.ok ? "ok" : "bad");
}

async function doCreate() {
  const missing = validate();
  if (missing.length) { show("还差这几项：\n· " + missing.join("\n· "), "bad"); return; }
  show("开工中…");
  const r = await fetch("/api/create", { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(form()) });
  const d = await r.json();
  if (!d.ok) { show(friendly(d.output ? d.output + "\n" + (d.error || "") : (d.error || "失败")), "bad"); return; }

