/* 可爱动物图鉴 —— 产品视觉层样式（literary-ink 图鉴手记变体）
 *
 * 作用域：全部规则挂在 body[data-skin="cuteanimal"] 下，与默认模板和其他
 * 产品皮肤完全隔离。
 *
 * 世界观：图鉴手记。米纸底 + 图鉴格线、装订虚线双框、衬线字、柿橙批注色；
 * 结果卡 = 手写 SVG 动物记号 + 名字 + share_line + reading（文学/说明书两档，
 * 数据驱动切换）。与缝纫手记（little-women）的差异：底纹格线化、批注色柿橙化、
 * 立绘位为几何平涂动物记号。
 */

body[data-skin="cuteanimal"] {
  --ca-ink: #3A3F35;
  --ca-soft: #7A776A;
  --ca-card: #FBF7EC;
  --ca-paper: #F5F0E3;
  --ca-clay: #C4622D;
  --ca-hairline: rgba(58, 63, 53, 0.4);
  --ca-serif: "Songti SC", "STSong", "Noto Serif SC", "SimSun", Georgia, serif;
  --ca-mono: ui-monospace, "SF Mono", Consolas, monospace;

  margin: 0;
  color: var(--ca-ink);
  font-family: var(--ca-serif);
  background-color: var(--ca-paper);
  background-image:
    repeating-linear-gradient(0deg, transparent 0 23px, rgba(58, 63, 53, 0.05) 23px 24px),
    repeating-linear-gradient(90deg, transparent 0 23px, rgba(58, 63, 53, 0.05) 23px 24px);
}

body[data-skin="cuteanimal"] .ca {
  max-width: 640px;
  min-height: 100vh;
  min-height: 100dvh;
  margin: 0 auto;
  padding: 14px 16px calc(28px + env(safe-area-inset-bottom, 0px));
}

/* ---------------------------------------------------------------- 骨架 ---- */
body[data-skin="cuteanimal"] .ca-top {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 14px;
  color: var(--ca-soft);
  font-size: 12px;
  letter-spacing: .12em;
}

body[data-skin="cuteanimal"] .ca-brand {
  color: var(--ca-ink);
  font-weight: 700;
  letter-spacing: .1em;
}

body[data-skin="cuteanimal"] .ca-eyebrow {
  margin: 0 0 10px;
  color: var(--ca-clay);
  font: 600 11px/1 Georgia, serif;
  letter-spacing: .3em;
  text-transform: uppercase;
}

body[data-skin="cuteanimal"] .ca-title {
  margin: 6px 0 12px;
  font-size: clamp(26px, 7.2vw, 40px);
  font-weight: 700;
  line-height: 1.52;
  letter-spacing: .02em;
}

body[data-skin="cuteanimal"] .ca-lead {
  margin: 0 auto;
  max-width: 26em;
  color: var(--ca-soft);
  font-size: 14.5px;
  line-height: 1.95;
}

body[data-skin="cuteanimal"] .ca-foot {
  margin: 24px 0 0;
  color: #8D8878;
  font-size: 11.5px;
  line-height: 1.8;
}

/* ---------------------------------------------------------------- 卡片 ----
   装订虚线双框 */
body[data-skin="cuteanimal"] .ca-card {
  max-width: 460px;
  margin: 0 auto;
  padding: 30px 26px;
  border: 1.5px dashed var(--ca-ink);
  border-radius: 6px;
  background: var(--ca-card);
  box-shadow: 0 0 0 4px var(--ca-paper), 0 0 0 5px var(--ca-hairline);
}

/* ---------------------------------------------------------------- 按钮 ---- */
body[data-skin="cuteanimal"] .ca-btn {
  padding: 13px 44px;
  border: 1.5px solid var(--ca-ink);
  border-radius: 6px;
  background: var(--ca-ink);
  color: var(--ca-paper);
  font: 700 15.5px/1 var(--ca-serif);
  letter-spacing: .22em;
  text-indent: .22em;
  cursor: pointer;
  transition: background-color .18s ease;
}

body[data-skin="cuteanimal"] .ca-btn:hover { background: #24281F; }
body[data-skin="cuteanimal"] .ca-btn-big { padding: 14px 50px; font-size: 16px; }

body[data-skin="cuteanimal"] .ca-link {
  padding: 2px 0;
  border: 0;
  border-bottom: 1.5px solid rgba(58, 63, 53, .3);
  background: transparent;
  color: var(--ca-soft);
  font: 500 13px/1.5 var(--ca-serif);
  letter-spacing: .1em;
  cursor: pointer;
}

body[data-skin="cuteanimal"] .ca-link:hover { color: var(--ca-clay); border-color: var(--ca-clay); }
body[data-skin="cuteanimal"] .ca-link:disabled { opacity: .35; cursor: not-allowed; }

/* ---------------------------------------------------------------- 入场 ---- */
body[data-skin="cuteanimal"] .ca-gate { margin-top: 7vh; text-align: center; }
body[data-skin="cuteanimal"] .ca-gate-lead { margin: 0 0 22px; }
body[data-skin="cuteanimal"] .ca-gate-form { display: flex; gap: 10px; }

body[data-skin="cuteanimal"] .ca-gate-input {
  flex: 1;
  min-width: 0;
  padding: 12px 14px;
  border: 1.5px dashed var(--ca-hairline);
  border-radius: 6px;
  background: #FFFDF6;
  color: var(--ca-ink);
  font: 600 14px/1.4 var(--ca-mono);
  letter-spacing: .06em;
}

body[data-skin="cuteanimal"] .ca-gate-input:focus-visible {
  outline: 0;
  border: 2px solid var(--ca-clay);
}

body[data-skin="cuteanimal"] .ca-gate .ca-btn { padding: 13px 30px; }

body[data-skin="cuteanimal"] .ca-gate-error {
  min-height: 20px;
  margin: 12px 0 0;
  color: var(--ca-clay);
  font-size: 13px;
}

/* ---------------------------------------------------------------- 封面 ---- */
body[data-skin="cuteanimal"] .ca-cover { margin-top: 4vh; text-align: center; }

body[data-skin="cuteanimal"] .ca-cast {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 8px;
  margin: 16px 0 4px;
}

body[data-skin="cuteanimal"] .ca-cast-dot {
  width: 18px;
  height: 18px;
  border-radius: 50%;
  border: 2px dashed rgba(58, 63, 53, .35);
  transition: transform .16s ease;
}

body[data-skin="cuteanimal"] .ca-cast-dot:hover { transform: scale(1.22); border-style: solid; }
body[data-skin="cuteanimal"] .ca-cover-actions { margin: 22px 0 0; }

/* ---------------------------------------------------------------- 答题 ---- */
body[data-skin="cuteanimal"] .ca-progress {
  height: 6px;
  margin: 2px 2px 14px;
  border-radius: 999px;
  background: rgba(255, 255, 255, .7);
  overflow: hidden;
}

body[data-skin="cuteanimal"] .ca-progress i {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: repeating-linear-gradient(90deg, var(--ca-clay) 0 10px, transparent 10px 16px);
  transition: width .3s ease;
}

body[data-skin="cuteanimal"] .ca-q-count {
  margin: 0 0 6px;
  color: var(--ca-clay);
  font: 700 12px/1 var(--ca-mono);
  letter-spacing: .2em;
}

body[data-skin="cuteanimal"] .ca-q-text {
  margin: 0 0 12px;
  padding: 15px 18px;
  border: 1.5px dashed var(--ca-hairline);
  border-radius: 6px;
  background: var(--ca-card);
  font-size: clamp(20px, 5.4vw, 26px);
  font-weight: 700;
  line-height: 1.62;
}

body[data-skin="cuteanimal"] .ca-options { display: grid; gap: 9px; }

body[data-skin="cuteanimal"] .ca-option {
  display: flex;
  gap: 12px;
  align-items: center;
  padding: 12px 15px;
  border: 1.5px dashed var(--ca-hairline);
  border-radius: 6px;
  background: var(--ca-card);
  color: var(--ca-ink);
  font: 400 15px/1.68 var(--ca-serif);
  text-align: left;
  cursor: pointer;
  transition: border-color .16s ease, background-color .16s ease;
  animation: ca-rise .4s cubic-bezier(.2, .7, .2, 1) both;
}

body[data-skin="cuteanimal"] .ca-option:nth-child(2) { animation-delay: .06s; }
body[data-skin="cuteanimal"] .ca-option:nth-child(3) { animation-delay: .12s; }

body[data-skin="cuteanimal"] .ca-option:hover { border-color: var(--ca-clay); border-style: solid; }

body[data-skin="cuteanimal"] .ca-option-key {
  display: grid;
  flex: 0 0 28px;
  width: 28px;
  height: 28px;
  place-items: center;
  border: 1.5px solid var(--ca-hairline);
  border-radius: 50%;
  color: var(--ca-soft);
  font: 700 12.5px/1 var(--ca-serif);
}

body[data-skin="cuteanimal"] .ca-option.picked {
  border: 1.5px solid var(--ca-clay);
  border-style: solid;
  background: color-mix(in srgb, var(--ca-clay) 8%, var(--ca-card));
}

body[data-skin="cuteanimal"] .ca-option.picked .ca-option-key {
  border-color: var(--ca-clay);
  background: var(--ca-clay);
  color: var(--ca-paper);
}

@keyframes ca-rise {
  0% { opacity: 0; transform: translateY(8px); }
  100% { opacity: 1; transform: translateY(0); }
}

body[data-skin="cuteanimal"] .ca-q-nav {
  display: flex;
  justify-content: space-between;
  margin-top: 12px;
}

/* ---------------------------------------------------------------- 等待 ---- */
body[data-skin="cuteanimal"] .ca-loading { margin-top: 10vh; text-align: center; }

body[data-skin="cuteanimal"] .ca-loading-text {
  margin: 8px 0 4px;
  font-weight: 700;
  font-size: 16px;
  letter-spacing: .16em;
}

/* ---------------------------------------------------------------- 结果 ---- */
body[data-skin="cuteanimal"] .ca-result { margin-top: 1vh; }

body[data-skin="cuteanimal"] .ca-portrait {
  height: min(38vh, 500px);
  height: min(38dvh, 500px);
  aspect-ratio: 4 / 5;
  width: auto;
  max-width: 100%;
  margin: 0 auto;
  border-radius: 6px;
  border: 1.5px dashed color-mix(in srgb, var(--ca-clay, #C4622D) 70%, transparent);
  overflow: hidden;
  background: var(--ca-paper);
}

body[data-skin="cuteanimal"] .ca-portrait img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: contain;
}

body[data-skin="cuteanimal"] .ca-portrait.ca-no-art { display: grid; place-items: center; }
body[data-skin="cuteanimal"] .ca-fallback { display: none; font-size: 44px; color: var(--ca-accent, var(--ca-clay)); }
body[data-skin="cuteanimal"] .ca-portrait.ca-no-art .ca-fallback { display: block; }

body[data-skin="cuteanimal"] .ca-name-row {
  display: flex;
  align-items: baseline;
  justify-content: center;
  margin: 14px 0 0;
}

body[data-skin="cuteanimal"] .ca-name {
  margin: 0;
  font-size: clamp(26px, 7.4vw, 38px);
  font-weight: 700;
  color: var(--ca-accent, var(--ca-ink));
  letter-spacing: .04em;
}

body[data-skin="cuteanimal"] .ca-quote {
  margin: 12px auto 0;
  max-width: 26em;
  text-align: center;
  font-size: clamp(18px, 5vw, 22px);
  font-weight: 700;
  line-height: 1.65;
  letter-spacing: .04em;
}

body[data-skin="cuteanimal"] .ca-modes {
  display: flex;
  justify-content: center;
  gap: 18px;
  margin: 6px 0 10px;
}

body[data-skin="cuteanimal"] .ca-mode {
  padding: 2px 1px;
  border: 0;
  border-bottom: 1.5px solid transparent;
  background: transparent;
  color: var(--ca-soft);
