readFileState.content:
/* 可爱动物图鉴 —— 产品视觉层样式（literary-ink 图鉴手记变体）
 *
 * 作用域：全部规则挂在 body[data-skin="cuteanimal"] 下，与默认模板和其他
 * 产品皮肤完全隔离。
 *
 * 世界观：图鉴手记。米纸底 + 图鉴格线、装订虚线双框、衬线字、柿橙批注色；
 * 结果卡 = 手写 SVG 动物记号 + 名字 + share_line + reading（文学/说明书两档，
 * 数据驱动切换）。与缝纫手记（little-women）的差异：底纹格线化、批注色柿橙化、
 * 立绘位为几何平涂动物记号。
 */

body[data-skin="cuteanimal"] {
  --ca-ink: #3A3F35;
  --ca-soft: #7A776A;
  --ca-card: #FBF7EC;
  --ca-paper: #F5F0E3;
  --ca-clay: #C4622D;
  --ca-hairline: rgba(58, 63, 53, 0.4);
  --ca-serif: "Songti SC", "STSong", "Noto Serif SC", "SimSun", Georgia, serif;
  --ca-mono: ui-monospace, "SF Mono", Consolas, monospace;

  margin: 0;
  color: var(--ca-ink);
  font-family: var(--ca-serif);
  background-color: var(--ca-paper);
  background-image:
    repeating-linear-gradient(0deg, transparent 0 23px, rgba(58, 63, 53, 0.05) 23px 24px),
    repeating-linear-gradient(90deg, transparent 0 23px, rgba(58, 63, 53, 0.05) 23px 24px);
}

body[data-skin="cuteanimal"] .ca {
  max-width: 640px;
  min-height: 100vh;
  min-height: 100dvh;
  margin: 0 auto;
  padding: 14px 16px calc(28px + env(safe-area-inset-bottom, 0px));
}

/* ---------------------------------------------------------------- 骨架 ---- */
body[data-skin="cuteanimal"] .ca-top {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 14px;
  color: var(--ca-soft);
  font-size: 12px;
  letter-spacing: .12em;
}

body[data-skin="cuteanimal"] .ca-brand {
  color: var(--ca-ink);
  font-weight: 700;
  letter-spacing: .1em;
}

body[data-skin="cuteanimal"] .ca-eyebrow {
  margin: 0 0 10px;
  color: var(--ca-clay);
  font: 600 11px/1 Georgia, serif;
  letter-spacing: .3em;
  text-transform: uppercase;
}

body[data-skin="cuteanimal"] .ca-title {
  margin: 6px 0 12px;
  font-size: clamp(26px, 7.2vw, 40px);
  font-weight: 700;
  line-height: 1.52;
  letter-spacing: .02em;
}

body[data-skin="cuteanimal"] .ca-lead {
  margin: 0 auto;
  max-width: 26em;
  color: var(--ca-soft);
  font-size: 14.5px;
  line-height: 1.95;
}

body[data-skin="cuteanimal"] .ca-foot {
  margin: 24px 0 0;
  color: #8D8878;
  font-size: 11.5px;
  line-height: 1.8;
}

/* ---------------------------------------------------------------- 卡片 ----
   装订虚线双框 */
body[data-skin="cuteanimal"] .ca-card {
  max-width: 460px;
  margin: 0 auto;
  padding: 30px 26px;
  border: 1.5px dashed var(--ca-ink);
  border-radius: 6px;
  background: var(--ca-card);
  box-shadow: 0 0 0 4px var(--ca-paper), 0 0 0 5px var(--ca-hairline);
}

/* ---------------------------------------------------------------- 按钮 ---- */
body[data-skin="cuteanimal"] .ca-btn {
  padding: 13px 44px;
  border: 1.5px solid var(--ca-ink);
  border-radius: 6px;
  background: var(--ca-ink);
  color: var(--ca-paper);
  font: 700 15.5px/1 var(--ca-serif);
  letter-spacing: .22em;
  text-indent: .22em;
