  font: 700 12px/1 var(--ca-mono);
  letter-spacing: .2em;
}

body[data-skin="cuteanimal"] .ca-q-text {
  margin: 0 0 12px;
  padding: 15px 18px;
  border: 1.5px dashed var(--ca-hairline);
  border-radius: 6px;
  background: var(--ca-card);
  font-size: clamp(20px, 5.4vw, 26px);
  font-weight: 700;
  line-height: 1.62;
}

body[data-skin="cuteanimal"] .ca-options { display: grid; gap: 9px; }

body[data-skin="cuteanimal"] .ca-option {
  display: flex;
  gap: 12px;
  align-items: center;
  padding: 12px 15px;
  border: 1.5px dashed var(--ca-hairline);
  border-radius: 6px;
  background: var(--ca-card);
  color: var(--ca-ink);
  font: 400 15px/1.68 var(--ca-serif);
  text-align: left;
  cursor: pointer;
  transition: border-color .16s ease, background-color .16s ease;
  animation: ca-rise .4s cubic-bezier(.2, .7, .2, 1) both;
