const SKIN_ID = "cuteanimal";
const THEME = "cuteanimal";

const esc = (value) =>
  String(value ?? "").replace(/[&<>"']/g, (ch) => (
    { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[ch]
  ));

const CAST = [
  { id: "capybara", name: "水豚", color: "#A97B4F" },
  { id: "hamster", name: "仓鼠", color: "#C99A3F" },
  { id: "sloth", name: "树懒", color: "#8A9A5B" },
  { id: "otter", name: "海獭", color: "#7A6A54" },
  { id: "rabbit", name: "兔子", color: "#C99898" },
  { id: "fox", name: "狐狸", color: "#C4622D" },
  { id: "penguin", name: "企鹅", color: "#3E5468" },
  { id: "owl", name: "猫头鹰", color: "#6E5B8C" },
];

const STYLE_LABELS = { literary: "文学", manual: "说明书", cold: "冷读", oracle: "占卜", letter: "信件" };

const colorOf = (result) => {
  const cast = CAST.find((c) => c.id === (result && result.id));
  return (cast && cast.color) || "#C4622D";
};

function styleEntries(result) {
  const entries = [];
  if (result.reading) entries.push(["literary", STYLE_LABELS.literary, result.reading]);
  Object.keys(result)
    .filter((k) => k.startsWith("reading_") && typeof result[k] === "string" && result[k])
    .forEach((k) => {
      const id = k.slice("reading_".length);
      entries.push([id, STYLE_LABELS[id] || id, result[k]]);
