readFileState.content:
/* 可爱动物图鉴 —— 产品视觉层（literary-ink 图鉴手记变体）
 *
 * 世界观：图鉴手记。米纸格线底、装订虚线双框、柿橙批注色；结果卡 = 手写 SVG
 * 动物记号 + 名字 + share_line + reading。解读风格层为数据驱动：
 * 结果对象上有什么 reading_* 字段就渲染什么档位（文学/说明书），
 * 皮肤只做表达：评分、题库、网络一律不进本文件。
 */

const SKIN_ID = "cuteanimal";
const THEME = "cuteanimal";

const esc = (value) =>
  String(value ?? "").replace(/[&<>"']/g, (ch) => (
    { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[ch]
  ));

const CAST = [
  { id: "capybara", name: "水豚", color: "#A97B4F" },
  { id: "hamster", name: "仓鼠", color: "#C99A3F" },
  { id: "sloth", name: "树懒", color: "#8A9A5B" },
  { id: "otter", name: "海獭", color: "#7A6A54" },
  { id: "rabbit", name: "兔子", color: "#C99898" },
  { id: "fox", name: "狐狸", color: "#C4622D" },
  { id: "penguin", name: "企鹅", color: "#3E5468" },
  { id: "owl", name: "猫头鹰", color: "#6E5B8C" },
];

const STYLE_LABELS = { literary: "文学", manual: "说明书", cold: "冷读", oracle: "占卜", letter: "信件" };

const colorOf = (result) => {
  const cast = CAST.find((c) => c.id === (result && result.id));
  return (cast && cast.color) || "#C4622D";
};

function styleEntries(result) {
  const entries = [];
  if (result.reading) entries.push(["literary", STYLE_LABELS.literary, result.reading]);
  Object.keys(result)
    .filter((k) => k.startsWith("reading_") && typeof result[k] === "string" && result[k])
    .forEach((k) => {
      const id = k.slice("reading_".length);
      entries.push([id, STYLE_LABELS[id] || id, result[k]]);
    });
  return entries;
}

function pageShell(inner) {
  return `<div class="ca">${inner}</div>`;
}

function brandBar(right) {
  return `<header class="ca-top"><span class="ca-brand">可爱动物图鉴</span><span class="ca-top-right">${right}</span></header>`;
}

function resultImage(resultId, name, accent) {
  const src = `/assets/cuteanimal/${encodeURIComponent(resultId)}.svg`;
  return `
    <figure class="ca-portrait" style="--ca-accent:${accent}">
      <img src="${src}" alt="${esc(name || resultId || "动物")}图鉴记号" loading="eager" decoding="async"
           onerror="this.closest('figure').classList.add('ca-no-art'); this.remove();">
      <span class="ca-fallback" aria-hidden="true">❋</span>
    </figure>`;
}

/* ----------------------------------------------------------- 回执 ---- */
const GATE_ERRORS = {
  empty: "先输入兑换码。",
  already_bound: "这个码已在别的浏览器激活。换设备请联系卖家重置绑定。",
  rate_limited: "尝试太频繁了，稍等一分钟再来。",
  invalid: "兑换码无效，检查一下再试。",
};

function gateView(ctx) {
  const html = pageShell(`
    ${brandBar("登记入口")}
    <section class="ca-card ca-gate">
      <p class="ca-eyebrow">Field Guide</p>
      <h1 class="ca-title">登记你的兑换码</h1>
      <p class="ca-lead">输入兑换码开始。激活后与当前浏览器绑定，之后随时回来。</p>
      <div class="ca-gate-form">
        <input id="ca-gate-code" class="ca-gate-input" type="text" autocomplete="off"
               autocapitalize="characters" spellcheck="false" placeholder="MYTHIC-XXXXX-XXXXX" aria-label="兑换码">
        <button class="ca-btn" id="ca-gate-submit">开始</button>
      </div>
      <p class="ca-gate-error" id="ca-gate-error" role="alert">${esc(ctx.message || "")}</p>
      <p class="ca-foot">兑换码在小红书店铺购买后获得。更换浏览器或清除数据后需重新激活，届时可联系卖家重置。</p>
    </section>`);
  const bind = (root) => {
    const input = root.querySelector("#ca-gate-code");
    const submit = root.querySelector("#ca-gate-submit");
    const error = root.querySelector("#ca-gate-error");
    const show = (text) => { error.textContent = text; };
    const run = async () => {
      const outcome = await ctx.submit(input.value);
      if (outcome.type === "unlocked") return;
      if (outcome.type === "other-product") {
        show(`这个码属于《${outcome.name}》，请打开对应测试的网址使用。`);
        return;
      }
      show(GATE_ERRORS[outcome.kind] || "兑换码无效，检查一下再试。");
      input.focus();
    };
    submit.addEventListener("click", run);
    input.addEventListener("keydown", (event) => {
      if (event.key === "Enter") { event.preventDefault(); run(); }
    });
  };
  return { html, bind };
}

/* ----------------------------------------------------------- 封面 ---- */
function coverView(ctx) {
  const html = pageShell(`
    ${brandBar("登记入口")}
