/* -------------------------------------------------------- 分享结果图 ---- */
function drawShareImage({ result }) {
  const canvas = document.createElement("canvas");
  canvas.width = 900;
  canvas.height = 1200;
  const c = canvas.getContext("2d");
  const accent = colorOf(result);

  const paper = () => {
    c.fillStyle = "#F5F0E3";
    c.fillRect(0, 0, 900, 1200);
    c.strokeStyle = "#3A3F35";
    c.lineWidth = 5;
    c.setLineDash([18, 14]);
    c.strokeRect(42, 42, 816, 1116);
    c.setLineDash([]);
    c.lineWidth = 2;
    c.strokeStyle = "rgba(58, 63, 53, 0.4)";
    c.strokeRect(60, 60, 780, 1080);
  };

  const center = (text, y, font, color) => {
    c.font = font;
    c.fillStyle = color;
    c.textAlign = "center";
    c.fillText(text, 450, y);
  };

  paper();
  center("可爱动物图鉴 · 原创娱乐测试", 130, "600 28px 'PingFang SC', 'Microsoft YaHei', sans-serif", "#7A776A");

  const img = new Image();
  img.onload = () => {
    const w = 470;
    const h = (img.height / img.width) * w;
    const x = (900 - w) / 2;
    const y = 180;
    c.drawImage(img, x, y, w, h);
    finish(y + h + 90);
  };
  img.onerror = () => finish(560);

  function finish(top) {
    center(result.name || "", top, "800 78px 'Songti SC', 'PingFang SC', sans-serif", accent);
    center(result.subtitle || "", top + 50, "400 30px 'PingFang SC', 'Microsoft YaHei', sans-serif", "#7A776A");
    const line = result.share_line || "";
    c.font = "600 38px 'PingFang SC', 'Microsoft YaHei', sans-serif";
    c.fillStyle = "#3A3F35";
    c.textAlign = "center";
    const rows = wrap(c, line, 680);
    rows.forEach((rowText, i) => c.fillText(rowText, 450, top + 116 + i * 56));

    CAST.forEach((cast, i) => {
      c.fillStyle = cast.color;
      c.beginPath();
      c.arc(450 - (CAST.length - 1) * 13 + i * 26, 1080, 6, 0, Math.PI * 2);
      c.fill();
    });
    center("结果由答题选择生成 · 原创演绎 · 非科学人格测评", 1130, "300 22px 'PingFang SC', 'Microsoft YaHei', sans-serif", "#8D8878");

    canvas.toBlob((blob) => {
      if (!blob) return;
      const link = document.createElement("a");
      link.download = `cuteanimal-${result.id || "result"}.png`;
      link.href = URL.createObjectURL(blob);
      link.click();
      window.setTimeout(() => URL.revokeObjectURL(link.href), 1000);
    }, "image/png");
  }
}

function wrap(c, text, maxWidth) {
  const rows = [];
  let current = "";
  for (const ch of String(text || "")) {
    if (c.measureText(current + ch).width > maxWidth) { rows.push(current); current = ch; }
    else current += ch;
  }
  if (current) rows.push(current);
  return rows;
}

