  if (current) rows.push(current);
  return rows;
}

export default {
  id: SKIN_ID,
  title: "测测更像是哪种可爱动物",
  copyText(result) {
    return `${result.name || ""}\n${result.share_line || ""}\n\n来自「可爱动物图鉴」原创娱乐测试`;
  },
  share({ result }) {
    if (typeof document === "undefined") return;
    drawShareImage({ result });
  },
  views: {
    gate: gateView,
    cover: coverView,
    question: questionView,
    resultLoading: resultLoadingView,
    result: verdictView,
  },
};

