body[data-skin="cuteanimal"] .ca-portrait img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: contain;
}

body[data-skin="cuteanimal"] .ca-portrait.ca-no-art { display: grid; place-items: center; }
body[data-skin="cuteanimal"] .ca-fallback { display: none; font-size: 44px; color: var(--ca-accent, var(--ca-clay)); }
body[data-skin="cuteanimal"] .ca-portrait.ca-no-art .ca-fallback { display: block; }

body[data-skin="cuteanimal"] .ca-name-row {
  display: flex;
  align-items: baseline;
  justify-content: center;
  margin: 14px 0 0;
}

body[data-skin="cuteanimal"] .ca-name {
  margin: 0;
  font-size: clamp(26px, 7.4vw, 38px);
  font-weight: 700;
  color: var(--ca-accent, var(--ca-ink));
  letter-spacing: .04em;
}

body[data-skin="cuteanimal"] .ca-quote {
  margin: 12px auto 0;
  max-width: 26em;
  text-align: center;
  font-size: clamp(18px, 5vw, 22px);
  font-weight: 700;
  line-height: 1.65;
  letter-spacing: .04em;
}

body[data-skin="cuteanimal"] .ca-modes {
  display: flex;
  justify-content: center;
  gap: 18px;
  margin: 6px 0 10px;
}

body[data-skin="cuteanimal"] .ca-mode {
  padding: 2px 1px;
  border: 0;
  border-bottom: 1.5px solid transparent;
  background: transparent;
  color: var(--ca-soft);
  font: 500 12.5px/1.4 var(--ca-serif);
  letter-spacing: .2em;
  cursor: pointer;
  transition: color .15s ease, border-color .15s ease;
}

body[data-skin="cuteanimal"] .ca-mode:hover { color: var(--ca-ink); }
body[data-skin="cuteanimal"] .ca-mode.active {
  color: var(--ca-clay);
  border-bottom-color: var(--ca-clay);
}

/* 读法块：风格 = 整页内容。一句话档做大字，其余档为段落。 */
body[data-skin="cuteanimal"] .ca-style {
  margin: 10px auto 0;
  max-width: 27em;
  color: var(--ca-ink);
  font-size: 15px;
  line-height: 1.95;
  text-align: center;
}

body[data-skin="cuteanimal"] .ca-style[data-style="line"] {
  font-size: clamp(21px, 6.2vw, 28px);
  font-weight: 700;
  line-height: 1.6;
  letter-spacing: .04em;
}

body[data-skin="cuteanimal"] .ca-save { margin: 16px 0 0; text-align: center; }
body[data-skin="cuteanimal"] .ca-save .ca-btn { padding: 13px 42px; font-size: 15px; }

body[data-skin="cuteanimal"] .ca-minor {
  display: flex;
  justify-content: center;
  gap: 22px;
  margin-top: 8px;
}

/* ---------------------------------------------------------------- 窄屏 ---- */
@media (max-width: 420px) {
  body[data-skin="cuteanimal"] .ca { padding: 14px 13px 34px; }
  body[data-skin="cuteanimal"] .ca-card { padding: 24px 18px; }
  body[data-skin="cuteanimal"] .ca-gate-form { flex-direction: column; }
}

/* ---------------------------------------------------------------- 动效偏好 ---- */
@media (prefers-reduced-motion: reduce) {
  body[data-skin="cuteanimal"] .ca-option { animation: none; }
  body[data-skin="cuteanimal"] .ca-option,
  body[data-skin="cuteanimal"] .ca-cast-dot,
  body[data-skin="cuteanimal"] .ca-progress i { transition: none; }
}

