await check("a full 16-question run lands on a named result page", async () => {
  for (let i = 0; i < 16; i += 1) {
    const count = appEl.querySelector(".ca-q-count");
    assert(count, `question ${i + 1} missing`);
    appEl.querySelectorAll(".ca-option")[0].click();
    await sleep(340);
  }
  const name = appEl.querySelector(".ca-name");
  assert(name, "result name missing");
  const quote = appEl.querySelector(".ca-quote");
  assert(quote && quote.textContent.trim().length > 4, "share_line missing");
  const reading = appEl.querySelector(".ca-reading");
  assert(reading && reading.textContent.trim().length > 40, "reading portrait missing");
  assert(appEl.querySelector("#ca-share"), "save button missing");
  for (const id of ["#ca-copy", "#ca-again", "#ca-home"]) {
    assert(appEl.querySelector(id), `action ${id} missing`);
  }
  return `动物：${name.textContent}`;
});

await check("result page carries accent, SVG art, share_line and the manual style switcher", () => {
  const section = appEl.querySelector(".ca-result");
  assert(section.attributes.style && section.attributes.style.includes("--ca-accent"), "accent color not set on result");
  const img = appEl.querySelector(".ca-portrait img");
  assert(img, "portrait slot missing");
  assert(String(img.attributes.src).startsWith("/assets/cuteanimal/"), `art path wrong: ${img.attributes.src}`);
  assert(String(img.attributes.src).endsWith(".svg"), "field-guide family ships SVG marks");
  const modes = appEl.querySelectorAll(".ca-mode");
  assert(modes.length === 2, `expected literary+manual mode buttons, got ${modes.length}`);
  const byMode = (name) => modes.find((b) => b.dataset.mode === name);
  assert(byMode("manual"), "manual mode button missing");
  return "accent + svg art + modes";
});

await check("interpretation style switcher swaps reading between literary and manual", async () => {
  const reading = appEl.querySelector(".ca-reading");
  const literary = reading.textContent;
  const manualBtn = [...appEl.querySelectorAll(".ca-mode")].find((b) => b.dataset.mode === "manual");
  manualBtn.click();
