  assert(reading.textContent.trim().length > 20, "manual copy looks wrong");
  const literaryBtn = [...appEl.querySelectorAll(".ca-mode")].find((b) => b.dataset.mode === "literary");
  literaryBtn.click();
  await sleep(30);
  assert(reading.textContent === literary, "literary not restored");
  return "文学 ↔ 说明书";
});


