/* 宁缺毋滥（2026-10-12 用户裁定）：双面卡每面只有一个内容块——
   正面 = 图 + 名 + 一句话（subtitle 大字）；背面 = 图 + 名 + 一段（back_reading）。
   翻面即"句 → 段"的节奏。无切换、无风格标识、无复制按钮；动作一行三链。 */
function resultFace(result, en, side, blockText) {
  const label = `${result.id || "女神"} ${side === "front" ? "正面" : "背面"}艺术图`;
